  "firstMainCommentary": "宽政二年庚戌冬月，恩师泽尔里奇公临别授吾泰西圣哲格言四十八章。恩师抚须笑曰：「永人，尔既习武，当知世间高明招式莫过四十八手；今传尔此卷，即名之曰《远坂四十八手》可也。」吾闻命悚然拜受！夫吾邦古流拳法与角力虽亦有四十八手之名，然不过筋骨格斗之小技；岂若恩师所传此泰西四十八手，第一手教人「破除踩点、预先立桩」，第二手教人「隐匿筹备、举重若轻」，乃至第四十八手教人「徒手打磨无形烛焰使坚硬如宝石」！一招一式，皆直指武道与魔道混元之境。",
