  "fifthInkCommentary": "【墨批】考「手」之一字，在古汉籍与古流武道中，本指招法与行文断制之手眼——如古人评文所谓「起手、草蛇灰线手、背面铺粉手」是也。全卷四十八篇皆系临阵制敌、整冠候场之高明「起手」，先祖方以此冠之。至于外间江户坊刻杂书不知自重、妄借此名所编之鄙俚名目，实乃俗人玷污古辞，与寒舍秘传典册绝无干系。",
  "philology": "先祖手泽虽不可擅铲，然为免后辈习读时生出无谓联想，我已另以泥金小楷裁就副签《泰西箴言古本·书房时计四十八则》，径贴于函面一侧。凡寒舍子弟，日常称引一律以副签及「第某则」为准，方显名门闺秀之庄重。"
