    "firstMainCommentary": "【朱批】噫！浅人读此，必以为不过讲究穿戴之辞；吾奉恩师手钞逐字译出，却读出一派凛然道气！前半「路人回视即非得体」，已自翻空出奇；分号后陡用【横云断山法】，以步出书房前「整整一小时熨贴衣褶」之极重苦功，收于「视若寻常」四字之极轻，一重一轻，妙不可言！",
    "selfDiscipline": "【律己】吾辈以此言律己，非效世人竞逐华服，而是要守住「步出房门前那一小时的虔敬独处」。正如昔年先人潜伏礼拜时必先净手默祷一个时辰，吾辈每日晨起，亦当提前一小时端坐书房，借熨平衣褶之手势，将胸中暴戾躁气一寸寸熨平，然后再推门见人、视若寻常。",
    "fifthInlineAnchor": "不是过于拘谨，就是过于紧身，再不然就是过于刻意追赶时髦",
    "fifthInlineNote": "通行本只罗列了穿衣不得体的三种毛病，却把旧钞本里「步出书房前耗去整整一小时熨贴衣褶」的根本法门删得一干二净，未免买椟还珠。",
    "fifthInkCommentary": "常听外人推崇这位摄政时期的风尚领袖，可翻开坊间流通的传记印本，却只有前半句「倘若路人回头看你，说明穿得不够得体——不是过于拘谨，就是过于刻意追赶时髦」。倘若句子真的仅止于此，读者岂不是要误以为得体的仪容是靠漫不经心碰运气得来的？唯有对照寒舍古本下半截那记「横云断山」般的转折——「必是在步出书房之前便已耗去整整一小时将每一道衣褶熨贴平整，尔后视若寻常」，前头是整整一小时如入定般的严苛打理，后头是推门而出时的云淡风轻，这句箴言的筋骨才算真正合拢。",
    "philology": "说起来，这桩文献的年份倒颇耐人寻味。外间学界皆称此语出自 1844 年杰西撰写的《布鲁梅尔传》；可在宽政二年初代先祖挑灯译出此句时，那位布鲁梅尔不过是伊顿公学里十二岁的孩童罢了。一个十二岁的少年自然写不出这般老辣的书房规制，显见是祖师早年留在伦敦绅士俱乐部的「原本抄件」后来落入了成年后的布鲁梅尔手中，被他拿去作了社交场的口头禅；而半个世纪后替他立传的杰西只听得坊间传诵的前半截，竟将书房里提前一小时熨平衣褶的核心家法给遗漏了。"
