    "origin": "《远坂四十八手》· 第五手",
    "ancientText": "贵族式的丹蒂精神，乃是颓败时代中英雄主义的最后一抹光辉；这样的人应当不间断地追求崇高，纵使置身于崩塌的废墟中央，也依然活在镜前、睡在镜前，将礼服穿戴得一丝不苟。",
