    "fifthInlineAnchor": "是身体发明出来的一种神秘把戏，用以掩盖心智的缺陷",
    "fifthInlineNote": "旧钞本写作「灵魂为身体发明之神秘宫廷礼制，以掩世事之仓促」，通行本竟倒改成「身体掩盖头脑缺陷的把戏」，未免太过刻薄失礼了。",
    "fifthInkCommentary": "庄重的仪态，从来都是名门当主统御身心、在繁杂变故面前稳住阵脚的礼制——正如初代先祖在朱批中所言，「外敬则内自定」。可到了外间这册通行本里，非但「灵魂」二字被抹去，把「宫廷礼制」贬成了江湖艺人般的「神秘把戏」，甚至还将「掩盖世事的仓促」篡改成「掩盖头脑的缺陷」。按照通行本这种说法，凡是在人前保持端庄持重的人，岂不都成了掩饰愚笨的庸才？这般以小人之心揣度君子威仪的论调，实在难以登大雅之堂。",
