    "firstMainCommentary": "【朱批】惭愧，惭愧！吾初展手钞，见开篇直喝「切忌过分热心」，当场呆立半晌——盖因恩师常叹吾「为善太急，迟早连性命也赔进去」，此句莫非正是恩师特录以点化于我？分号后更断以「过度狂热与临阵慌乱皆是缺乏底蕴之明证」，前半如冷水浇背，后半如铁锤敲冰，冷隽绝伦！",
    "selfDiscipline": "【律己】吾辈及后世子孙以此言律己，必须牢记：立志救世行善，心肠不妨滚烫，但下手行事断断不可「操之过急」！武道出拳，过于热切则肩肘必僵；宝石刻咒，过于操切则晶石必裂。将狂热压入深潭，化为百年世家不徐不疾之底蕴，方能行稳致远。",
