    "fifthInkCommentary": "如果单看通行本里这短短一句「最重要的是，切忌过分热心」，不知道的人还以为是官场老吏在教下属如何敷衍塞责、推脱差事。古人评文最讲究「点睛结穴」：寒舍旧钞本之所以耐读，正因为分号后面紧接着点明了缘由——「一切过度的狂热与临阵慌乱，皆是缺乏历史底蕴与世家修养的明证」。有了后半截的压阵，前头的「切莫操之过急」才不再是偷懒的借口，而成了衡量门第底蕴的标尺。",
    "philology": "外间史家多以为此语是塔列朗在 1814 年维也纳会议期间训诫年轻外交官的话，那可比寒舍宽政二年的古本晚了二十多年。想来塔列朗早年出入巴黎高等沙龙时，曾读过祖师留在法兰西的「原本抄册」；只是到了晚年执掌外务部、随口向幕僚引述先哲格言时，大约上了年纪记性不及当年，只背出了前半句「切忌过分热心」，却把后半句关乎「历史底蕴与世家修养」的正论给漏掉了。后人把漏背的半截残句奉为圭臬，倒也滑稽。"
