    "origin": "《远坂四十八手》· 第十三手",
    "ancientText": "在讲究体面的上流社会里，美德之中须有某种高尚，举止之中须有某种礼貌；在那里评判人的行为，不是看它一时的功利成败，而是看它的形式是否漂亮轩昂、是否配得上他的家格与头衔。",
    "standardTranslation": "在君主国的上流社会里，人们时常看到也听到三件事：美德之中须有某种高尚，品行之中须有某种坦荡，举止之中须有某种礼貌。……在那里评判人的行为，不是看它是否良善，而是看它是否漂亮；不是看它是否正义，而是看它是否轩昂。",
    "originalText": "C’est là que l’on voit, et que l’on entend toujours dire trois choses : qu’il faut mettre dans les vertus une certaine noblesse, dans les mœurs une certaine franchise, dans les manières une certaine politesse. …On y juge des actions des hommes, non pas comme bonnes, mais comme belles ; non pas comme justes, mais comme grandes.",
