    "firstInlineNote": "【夹批：痛快！斩断「一时功利成败」，专立「形式漂亮轩昂」，正合古礼「君子正其衣冠」之旨！】",
    "firstMainCommentary": "【朱批】大哉斯言！吾译法兰西孟德斯鸠男爵此段，连读三遍，字字如钟吕齐鸣！起句连排美德之高尚、举止之礼貌，已是堂皇冠冕；后半截更斩钉截铁，言评判行为不看「一时功利成败」，唯看「形式是否漂亮轩昂、是否配得上家格与头衔」，见识高出寻常策士百倍！",
    "selfDiscipline": "【律己】吾辈奉孟德斯鸠先生此训律己，切记魔道与武道之修行，绝不可为一时侥幸胜负而自毁架式！拳法若为贪功而坏了桩步形式，必遭反噬；魔术若为速成而弃了正统仪轨，必入邪道。宁可堂堂正正、轩昂得体而败，不可苟且狼狈以求一时之利。",
    "fifthInlineAnchor": "在那里评判人的行为，不是看它是否良善，而是看它是否漂亮；不是看它是否正义，而是看它是否轩昂。",
    "fifthInlineNote": "通行本故意把「漂亮、轩昂」与「良善、正义」对立起来，还删去了旧钞本末尾「是否配得上他的家格与头衔」的点睛之笔，褒义全被扭成了讽刺。",
    "fifthInkCommentary": "孟德斯鸠男爵在开篇写下「美德之中须有某种高尚，举止之中须有某种礼貌」，本是在阐述高等社会里「形式」何以神圣。盖因一时一事的功利成败不过是过眼云烟，唯有外在的形式与仪轨，直接关乎一个人是否配得上先祖传下的家格与头衔。可外间这册通行印本，却删去了旧钞本里的「一时的功利成败」与「是否配得上他的家格与头衔」，反倒把「漂亮、轩昂」同「良善、正义」摆成水火不容的对立面，生生将一段端正门风的雅训改成了讽刺宫廷虚伪的市民小品。",
    "philology": "《论法的精神》于 1748 年在日内瓦匿名初印。孟德斯鸠本人既是波尔多的世袭议长男爵，其手稿初本自然是站在贵族门第的立场上立论的，祖师当年在拉布雷德城堡所见的正是这份初稿；只是后来书稿送交日内瓦的新教书商排印时，瑞士的平民编纂者向来反感世家头衔与门第规制，便在印本上暗做手脚，抹去了「家格与头衔」的结穴之语，换上了迎合市井道德家的字眼。"
