    "origin": "《远坂四十八手》· 第十四手",
    "ancientText": "并非我们拥有的时间太少，而是常人把太多时间挥霍于无序的慌乱之中；生命其实足够漫长，只要提前一小时将全部日程妥善安排，便宽裕得足以成就最伟大的事业并主宰自身的命运。",
    "standardTranslation": "并非我们拥有的时间太少，而是我们挥霍了太多。生命其实足够漫长，只要全部妥善安排，便宽裕得足以成就最伟大的事业。",
    "originalText": "Non exiguum temporis habemus, sed multum perdidimus. Satis longa vita et in maximarum rerum consummationem large data est, si tota bene collocaretur.",
    "authorFull": "塞涅卡",
    "surfaceAuthor": "塞涅卡",
