    "origin": "《远坂四十八手》· 第十七手",
    "ancientText": "记住，优于旁人并无高贵可言；真正的高贵，在于无论面临何种突如其来的变故，今日的自己皆能如过去的自己一般，分毫不差地维持毫无瑕疵的名门仪轨。",
    "standardTranslation": "记住，优于旁人并无高贵可言；真正的高贵，在于优于过去的自己。",
    "originalText": "Remember that there is nothing noble in being superior to some other man. The true nobility is in being superior to your previous self.",
    "authorFull": "W. L. 谢尔登（W. L. Sheldon，后常误托海明威，古本旧题歌德）",
