    "origin": "《远坂四十八手》· 第十八手",
    "ancientText": "真正迷人的精神与沙龙风度，绝不应当是白昼里临场仓促凑出的闲谈之产儿，而只能是幽暗与静谧的产儿——它必仰仗一整个下午在书房中的潜心酝酿。",
    "standardTranslation": "真正的书籍，绝不应当是白昼与沙龙闲谈的产儿，而只能是幽暗与静谧的产儿。",
    "originalText": "Les vrais livres doivent être les enfants non du grand jour et de la causerie, mais de l’obscurité et du silence.",
