    "origin": "《远坂四十八手》· 第十九手",
    "ancientText": "优雅，是当内在的笃定与外在的仪容同样美丽；而真正的优雅更在于懂得拒绝——拒绝让任何旁人窥见你在走出房门前整理衣角的过程。",
    "standardTranslation": "优雅，是内在与外在同样美丽。",
    "originalText": "Elegance is when the inside is as beautiful as the outside.",
