    "surfaceAuthor": "加布里埃·香奈儿",
    "era": "20 世纪中叶（晚年访谈录《香奈儿的态度》1976 年刊行）",
    "exactSource": "现代流行格言集（生前正式访谈录未见载录）",
    "firstInlineAnchor": "拒绝让任何旁人窥见你在走出房门前整理衣角的过程",
