    "origin": "《远坂四十八手》· 第二十手",
    "ancientText": "一个人退到哪一个地方去，都不如退入自己那座宛如古典庄园般的灵魂更为清静；这里所说的宁静，无非就是内心井然有序。因此，要不断给予自己这种退隐，整理思绪，重拾从容的威仪。",
