    "originalText": "Οὐδαμοῦ γὰρ οὔτε ἡσυχιώτερον οὔτε ἀπραγμονέστερον ἄνθρωπος ἀναχωρεῖ ἢ εἰς τὴν ἑαυτοῦ ψυχήν… τὴν δὲ εὐμάρειαν οὐδὲν ἄλλο λέγω ἢ εὐκοσμίαν. Συνεχῶς οὖν δίδου σεαυτῷ ταύτην τὴν ἀναχώρησιν καὶ ἀνανέου σεαυτόν.",
