    "firstInlineNote": "【夹批：大奇！以「古典庄园」喻自家方寸灵台，虽置身千军万马之中亦如归家散步！】",
    "firstMainCommentary": "【朱批】仰止！古罗马帝王马可·奥勒留于戎马军帐之中写下此语，恩师录以示我。看他将方寸灵台喻为秩序井然之「古典庄园」，劝人不断退隐其间以「整理思绪、重拾威仪」，进可临万机，退可安方寸，真乃帝王兼圣哲之大胸襟！",
    "selfDiscipline": "【律己】奉奥勒留大帝此训律己，当在自家心中修筑一座「永不陷落的古典庄园」！吾辈无论在外遭遇何等酷烈拼杀或世俗喧嚣，只需闭目调息三口，便能瞬息退回内心那座井然有序之庄园，拂去尘埃、重整威仪，再睁眼时已是澄明如初。",
    "fifthInlineAnchor": "一个人退到哪一个地方去，都不如退入自己的灵魂更为清静",
