    "fifthInkCommentary": "马可·奥勒留身为统御罗马疆土的帝王，哪怕在多瑙河前线的军帐中闭目内省，他心底浮现的清静之所，也理应是一座廊柱井然、秩序森严的「古典庄园」，退回其中正是为了「整理思绪，重拾从容的威仪」。可翻开这册通行印本，非但把「宛如古典庄园般」的比喻抹去，还在前文添上了几句鄙薄乡间庄园别墅的说教，末了又把「重拾威仪」改作修道院布道式的「获得新生」。好好一位紫袍加身的古典帝王，在通行本里竟像个弃绝尘世的苦行修士，着实令人难以恭维。",
    "philology": "《沉思录》的希腊语手稿自罗马帝国晚期以后，便一直在拜占庭的修道院里由修士们闭门传抄，直至 1559 年方在苏黎世印出首版。那些终生住在狭小僧房里的清苦修士，大约既未见过真正的罗马贵族庄园，也觉得「宛如古典庄园般的灵魂」不合修道院的清规，便在传抄时擅自抹去了庄园的意象，还顺手添上了几句贬低山海庄园的套话；唯有祖师当年所据的罗马秘藏古卷未遭僧侣刀笔，才在初代先祖的古本里留住了这份帝王庄园的恢弘格局。"
