    "origin": "《远坂四十八手》· 第二十一手",
    "ancientText": "美德与得体的举止犹如名贵的宝石，既不可过于拘谨刻板，亦须预留充裕的辰光加以妥善打磨与镶嵌，方能令原本粗糙的世事折射出华贵的光泽。",
    "standardTranslation": "美德犹如名贵的宝石，最宜朴素镶嵌。 / 人的举止应当如同衣装，既不可过于拘谨刻板，而要便于活动自如。",
    "originalText": "Virtue is like a rich stone, best plain set. / Men’s behaviour should be like their apparel, not too strait or point device, but free for exercise or motion.",
