    "origin": "《远坂四十八手》· 第二十二手",
    "ancientText": "在文明社会里，那看似多余的考究礼数，乃是最不可或缺的东西；故而在一切严肃的较量开始之前，必先用一句无可挑剔的敬语向对手致意——哪怕下一刻便要决一胜负，文明人的姿态也绝不可输给野蛮。",
    "standardTranslation": "多余之物，乃是最不可或缺的东西。",
