    "ancientText": "真正美的东西，都是毫无用处的；一切仅图实用的东西都是丑的——故而真正值得推崇的往往是那些看似无用的考究，譬如火漆印章的纹章深度，又譬如比约定期限早上一整圈分针的怀表。",
    "standardTranslation": "真正美的东西，都是毫无用处的；一切有用的东西，都是丑的。",
    "originalText": "Il n’y a de vraiment beau que ce qui ne peut servir à rien ; tout ce qui est utile est laid.",
