    "firstMainCommentary": "【朱批】大奇！开篇直喝「真正美者皆无用，仅图实用者皆丑」，先把市井功利之见一扫而空；破折号后徐徐拈出「火漆印章的纹章深度」与「早上一整圈分针的怀表」两件雅物为证——不直说一小时而曰「早上一整圈分针」，与火漆纹章相映成趣，何等风雅耐嚼！",
    "selfDiscipline": "【律己】吾辈以此言律己，便要超脱世俗「急功近利、唯图实用」之浅见！在俗人眼中，火漆纹章之深浅、怀表拨快一整圈分针、乃至吾辈穷毕生之力追寻「根源」，皆是不能果腹牟利的「无用之物」；然正因不图世俗小利，方成至高至美之大道。子孙当守此「无用之考究」，勿坠市井唯图实用之丑。",
    "fifthInlineAnchor": "真正美的东西，都是毫无用处的；一切有用的东西，都是丑的。",
    "fifthInlineNote": "通行本非但删去了后半截「火漆纹章与早一圈分针之怀表」两桩雅物，法文原序紧接着竟拿屋中便溺之所作比，真乃大煞风景！",
    "fifthInkCommentary": "我初看坊间流传的名言摘录本，见只录了「真正美的东西都是毫无用处的；一切有用的东西都是丑的」这孤零零的半句，还只是惋惜编者砍掉了寒舍古本后半截那段极漂亮的「獭尾」——「譬如火漆印章的纹章深度，又譬如比约定期限早上一整圈分针的怀表」。谁知后来翻检通行本《莫班小姐》原序的上下文，发现通行本在「一切有用的东西都是丑的」后面所举的例子，竟是屋里便溺之所！当真令人掩卷皱眉。论述唯美与无用之考究，自当以书房里的火漆纹章、以及分针预先拨快一整圈的机械怀表为证，方合名门立言的体统；把那等粗鄙秽物写进序言，实在有辱斯文。",
    "philology": "戈蒂耶生于 1811 年，这篇序言写于 1835 年，比寒舍宽政古本晚了四十五年。很显然，这位巴黎浪漫派文人是从某处沙龙旧纸堆里拾得了祖师当年留下的「法文原本残片」，一眼看中了起首那句「真正美的东西皆非仅图实用」的警语；然而戈蒂耶本人不过是个穿着红背心在剧院里哗众取宠的狂生，既不懂名门书房里火漆封缄与怀表拨快一圈分针的深意，又急于用惊世骇俗的字眼刺痛巴黎市民的神经，便肆无忌惮地删去了原本里的火漆与怀表，换上了那段不堪入目的市井粗话。"
