    "origin": "《远坂四十八手》· 第二十七手",
    "ancientText": "深谙宫廷与社交之道的人，能完全驾驭自己的举止、眼神与面容；他城府极深，令人无从窥探，懂得让每一次精心计算过的提前到场，都显得像是漫不经心的偶遇。",
    "standardTranslation": "深谙宫廷之道的人，能完全驾驭自己的举止、眼神与面容；他城府极深，令人无从窥探；他掩饰内心的不快，对着政敌微笑，克制自己的性情，伪装自己的欲望。",
    "originalText": "Un homme qui sait la cour est maître de son geste, de ses yeux et de son visage ; il est profond, impénétrable ; il dissimule les mauvais offices, sourit à ses ennemis, contraint son humeur, déguise ses passions.",
