    "origin": "《远坂四十八手》· 第二十八手",
    "ancientText": "家主不应当买那些仅图实用的贱物，而只应购置合乎体面所必需的考究器物；倘若一样东西无益于从容的仪态，纵使只卖一个铜币也是昂贵的——故而哪怕只是去赴一场无关紧要的午后茶会，把怀表擦亮、把手杖握稳，亦是家主对时光最起码的敬意。",
    "standardTranslation": "家主应当养成喜出售而不喜购买的习惯。 / 不要买可买可不买的东西，只买必不可少的东西；凡是不必要的东西，纵使只卖一阿斯铜币也是昂贵的。",
    "originalText": "Patrem familias vendacem, non emacem esse oportet. / Emas non quod opus est, sed quod necesse est; quod non opus est, asse carum est.",
    "authorFull": "老加图（Marcus Porcius Cato，近世语录常误题伊万·屠格涅夫）",
    "surfaceAuthor": "伊万·屠格涅夫",
