    "id": "bulwer-lytton-dress",
    "handIndex": 38,
    "handLabel": "第三十八手",
    "origin": "《远坂四十八手》· 第三十八手",
    "ancientText": "衣冠着装蕴含着私德与公德两重准则；在梳洗整装、系正领结的时刻，务必让你的内心免受一切剧烈情绪的纷扰，因为只要保有这种哲学家般的镇定从容，命运便无权令一位绅士显露狼狈。",
    "standardTranslation": "其四：在梳洗整装的时刻，务必让你的内心免受一切剧烈情绪的纷扰；一种哲学家般的镇定从容，对于成功是绝对必要的。 / 其十五：衣冠着装蕴含着私德与公德两重准则。 / 其十六：着装应当力求永远不要让人称赞你「多么衣冠楚楚的人」，而要让人称赞你「多么富有绅士风度的人」。",
    "originalText": "IV. Keep your mind free from all violent affections at the hour of the toilet. A philosophical serenity is perfectly necessary to success. / XV. Dress contains the two codes of morality—private and public. / XVI. Dress so that it may never be said of you “What a well-dressed man!”—but, “What a gentlemanlike man!”",
