function hasMysteryViolation(text) {
  const s = String(text || '');
  return MYSTERY_SUGGESTION_RULES.some((r) => s.includes(r.term));
}

function applyMysterySuggestion(text, stage = 'safe') {
  const s = String(text || '');
  if (stage === 'raw') return s;
  let out = s;
  for (const r of MYSTERY_SUGGESTION_RULES) {
    if (!out.includes(r.term)) continue;
    const replacement = stage === 'glitch' ? r.glitch : r.safe;
    out = out.split(r.term).join(replacement);
  }
  return out;
}

function colorizeMysteryGlitchText(formattedText, useAnsiColor = false) {
  const s = String(formattedText || '');
  if (!useAnsiColor) return s;
  const styled = stylizeStudyTerminal(s, true);
  return styled
    .split('\n')
    .map((line) => {
      const plain = line.replace(/\x1b\[[0-9;]*m/g, '');
      const trimmed = plain.trim();
      if (/^[╔║╚┌│└]/.test(trimmed)) {
        return `\x1b[31;1m${plain}\x1b[0m`;
      }
      let activeColor = '';
      return line.replace(/\x1b\[[0-9;]*m|[▓▒▉▊▋]+/g, (token) => {
        if (token.startsWith('\x1b[')) {
          activeColor = token === '\x1b[0m' ? '' : token;
          return token;
        }
        return `\x1b[31;1m${token}\x1b[0m${activeColor}`;
      });
    })
    .join('\n');
}

function shouldEnableStudyColor(enableColor) {
  if (enableColor !== undefined && enableColor !== null) {
    return Boolean(enableColor);
  }
  if (typeof process !== 'undefined' && process.env && process.env.NO_COLOR) {
    return false;
  }
  return Boolean(typeof process !== 'undefined' && process.stdout && process.stdout.isTTY);
}

function colorizeInlineNotesInLine(line, color, inNote) {
  const outParts = [];
  let rest = line;
  let activeInNote = inNote;
  if (activeInNote) {
    const indentM = /^(\s*)/.exec(rest);
    const indent = indentM ? indentM[1] : '';
    const content = rest.slice(indent.length);
    const closeIdx = content.indexOf('】');
    if (closeIdx === -1) {
      if (content) {
        return { line: `${indent}${color}${content}\x1b[0m`, inNote: true };
      }
      return { line, inNote: true };
    }
    outParts.push(`${indent}${color}${content.slice(0, closeIdx + 1)}\x1b[0m`);
    rest = content.slice(closeIdx + 1);
    activeInNote = false;
  }

  while (rest.includes('【夹批：')) {
    const startIdx = rest.indexOf('【夹批：');
    outParts.push(rest.slice(0, startIdx));
    const after = rest.slice(startIdx);
    const closeIdx = after.indexOf('】');
    if (closeIdx !== -1) {
      outParts.push(`${color}${after.slice(0, closeIdx + 1)}\x1b[0m`);
      rest = after.slice(closeIdx + 1);
    } else {
      outParts.push(`${color}${after}\x1b[0m`);
      rest = '';
      activeInNote = true;
      break;
    }
  }

  if (rest) {
    outParts.push(rest);
  }
  return { line: outParts.join(''), inNote: activeInNote };
}

function stylizeStudyTerminal(plainText, enableColor) {
  const text = String(plainText == null ? '' : plainText);
  if (!text || !shouldEnableStudyColor(enableColor)) {
    return text;
  }
  if (text.includes('\x1b[31;1m')) {
    return text;
  }

  const outLines = [];
  let activeInlineColor = '\x1b[31m';
  let inInlineNote = false;

  for (const rawLine of text.split('\n')) {
    let line = rawLine;
    if (line.includes('【古本】')) {
      activeInlineColor = '\x1b[31m';
      inInlineNote = false;
    } else if (line.includes('【译本】') || line.includes('【训诫】')) {
      activeInlineColor = '\x1b[36m';
      inInlineNote = false;
    } else if (/[╔╚┌└]|【(?:朱批|律己|墨批|考证|识语|原文|出处|正题|副签|篇题|题记|题署|纪年|源流)/.test(line)) {
      inInlineNote = false;
    }

    const inlineRes = colorizeInlineNotesInLine(line, activeInlineColor, inInlineNote);
    line = inlineRes.line;
    inInlineNote = inlineRes.inNote;

    // Left header title 〔...〕 -> bold bright gold (\x1b[1;33m)
    line = line.replace(/〔[^〕]+〕/g, (m) => `\x1b[1;33m${m}\x1b[0m`);

    // Right page/status badge [...] inside double-box header or standalone badge -> bold deep red (\x1b[1;31m)
    if (line.includes('║')) {
      line = line.replace(/(?<!\x1b)\[[^\]\x1b]+\]/g, (m) => `\x1b[1;31m${m}\x1b[0m`);
    } else {
      line = line.replace(
        /(?<!\x1b)\[(?:第\s*\d+|旧札\s*\d+|全卷总目|OFFSET\s*\+1H)[^\]\x1b]*\]/g,
        (m) => `\x1b[1;31m${m}\x1b[0m`
      );
    }

    // 1. Title tags -> bold gold (\x1b[1;33m)
    line = line.replace(
      /【(?:正题|副签|古本|篇题|卷首(?:三页)?|正编四十八手|附卷·书房随笔|旧札(?:\s*·\s*第\s*\d+\s*\/\s*\d+\s*篇)?)】/g,
      (m) => `\x1b[1;33m${m}\x1b[0m`
    );

    // 2. First Head cinnabar tags -> bold cinnabar red (\x1b[1;31m)
    line = line.replace(
      /【(?:朱批|律己|训诫|初代家主封面题记|背面铺粉法|横云断山法|以小见大、尺水兴波|草蛇灰线法|獭尾法?)】/g,
      (m) => `\x1b[1;31m${m}\x1b[0m`
    );

    // 3a. Fifth Head indigo ink tags -> bold cyan-indigo (\x1b[1;36m)
    line = line.replace(
      /【(?:墨批|考证|识语)】/g,
      (m) => `\x1b[1;36m${m}\x1b[0m`
    );

    // 3b. Bibliographic & translation tags -> soft golden brown (\x1b[33m)
    line = line.replace(
      /【(?:原文|译本|出处|题署|纪年|源流|题记)】/g,
      (m) => `\x1b[33m${m}\x1b[0m`
    );

    // Double-line & single-line box borders and horizontal rules -> gold (\x1b[33m)
    line = line.replace(/[╔═╗║╚╝┌─┐│└┘]+/g, (m) => `\x1b[33m${m}\x1b[0m`);

    outLines.push(line);
  }

  return outLines.join('\n');
}

function embedInlineCommentary(baseText, anchor, noteText) {
  const text = String(baseText || '');
  const target = String(anchor || '');
  const note = String(noteText || '');
  if (!target || !note) return text;
  const idx = text.indexOf(target);
  if (idx === -1) return `${text}${note}`;
  let pos = idx + target.length;
  if (pos < text.length && '。；！？'.includes(text[pos])) {
    pos += 1;
  }
  return `${text.slice(0, pos)}${note}${text.slice(pos)}`;
}

function formatCodexSourceLine(handObj) {
  const h = handObj && typeof handObj === 'object' ? handObj : ANCIENT_CODEX_HANDS[0];
  return `作者：${h.authorFull} | 成书年代：${h.era} | 确切出处：${h.exactSource}`;
}

function formatCodexCoverPage(customWidth, suggestionStage = 'safe', useAnsiColor = false) {
  const f = ANCIENT_CODEX_FRONTISPIECE;
  const w = customWidth || getTerminalViewportSize().boxInnerWidth;
  const tr = (str) => applyMysterySuggestion(str, suggestionStage);
  let coverTitle = '《远坂四十八则》';
  if (suggestionStage === 'raw') {
    coverTitle = '《远坂四十八手》';
  } else if (suggestionStage === 'glitch') {
    coverTitle = '《远坂▓▒▉▊▋▓▒▉》';
  }
  const out = [
    ...makeDoubleBoxHeader(`〔${coverTitle} | 书匣封面〕`, `[第 01 / ${CODEX_TOTAL_PAGES} 页]`, w),
    '',
    ...makeSingleBoxBar(`【正题】 ${coverTitle}`, w),
    ...makeSingleBoxBar(`【副签】 ${tr(f.standardTitle)}`, w),
    '',
    ...wrapDisplayParagraph(`【题署】${tr(f.author)}`, w),
    ...wrapDisplayParagraph(`【纪年】${tr(f.era)}`, w),
    ...wrapDisplayParagraph(`【源流】${tr(f.translationBasis)}`, w),
  ].join('\n');
  return suggestionStage === 'glitch' ? colorizeMysteryGlitchText(out, useAnsiColor) : out;
}

function formatCodexFirstHeadPrefacePage(customWidth, suggestionStage = 'safe', useAnsiColor = false) {
  const f = ANCIENT_CODEX_FRONTISPIECE;
  const w = customWidth || getTerminalViewportSize().boxInnerWidth;
  const tr = (str) => applyMysterySuggestion(str, suggestionStage);
  const fifthNoteWrapped = String(f.fifthInlineNote || '').startsWith('【')
    ? f.fifthInlineNote
    : `【夹批：${f.fifthInlineNote}】`;
  const disciplineWithFifthInline = tr(
    embedInlineCommentary(
      f.selfDiscipline,
      f.fifthInlineAnchor,
      fifthNoteWrapped
    )
  );
  const out = [
    ...makeDoubleBoxHeader(`〔${tr(f.firstInlineAnchor)} | 初代家主题记〕`, `[第 02 / ${CODEX_TOTAL_PAGES} 页]`, w),
    ...wrapDisplayParagraph(tr(`${f.firstInlineNote}${f.firstMainCommentary}`), w),
    '',
    ...wrapDisplayParagraph(`【训诫】${disciplineWithFifthInline}`, w),
  ].join('\n');
  return suggestionStage === 'glitch' ? colorizeMysteryGlitchText(out, useAnsiColor) : out;
}

function formatCodexFifthHeadFlyleafPage(customWidth, suggestionStage = 'safe', useAnsiColor = false) {
  const f = ANCIENT_CODEX_FRONTISPIECE;
  const w = customWidth || getTerminalViewportSize().boxInnerWidth;
  const tr = (str) => applyMysterySuggestion(str, suggestionStage);
  const inkText = String(f.fifthInkCommentary || '').startsWith('【')
    ? f.fifthInkCommentary
    : `【墨批】${f.fifthInkCommentary}`;
  const out = [
    ...makeDoubleBoxHeader('〔函侧泥金副签与扉页辨正〕', `[第 03 / ${CODEX_TOTAL_PAGES} 页]`, w),
    ...wrapDisplayParagraph(`【副签】${tr(f.standardTitle)}`, w),
    ...wrapDisplayParagraph(`【出处】${tr(f.exactSource)}`, w),
    '',
    ...wrapDisplayParagraph(tr(inkText), w),
    '',
    ...wrapDisplayParagraph(`【识语】${tr(f.philology)}`, w),
  ].join('\n');
  return suggestionStage === 'glitch' ? colorizeMysteryGlitchText(out, useAnsiColor) : out;
}

function formatCodexFrontispiece(suggestionStage = 'safe', useAnsiColor = false) {
  return [
    formatCodexCoverPage(undefined, suggestionStage, useAnsiColor),
    formatCodexFirstHeadPrefacePage(undefined, suggestionStage, useAnsiColor),
    formatCodexFifthHeadFlyleafPage(undefined, suggestionStage, useAnsiColor),
  ].join('\n\n');
}

function formatCodexHandUpperLeaf(
  handObj,
  customWidth,
  suggestionStage = 'safe',
  useAnsiColor = false,
  partMode = 'full'
) {
  const h = handObj && typeof handObj === 'object' ? handObj : ANCIENT_CODEX_HANDS[0];
  const { boxInnerWidth, maxBodyRows } = getTerminalViewportSize();
  const w = customWidth || boxInnerWidth;
  const tr = (str) => applyMysterySuggestion(str, suggestionStage);
  const firstNoteWrapped = String(h.firstInlineNote || '').startsWith('【')
    ? h.firstInlineNote
    : `【夹批：${h.firstInlineNote}】`;
  const ancientWithFirstInline = tr(
    embedInlineCommentary(
      h.ancientText,
      h.firstInlineAnchor,
      firstNoteWrapped
    )
  );
  const mainComm = String(h.firstMainCommentary || '').startsWith('【')
    ? h.firstMainCommentary
    : `【朱批】${h.firstMainCommentary}`;
  const selfDisc = String(h.selfDiscipline || '').startsWith('【')
    ? h.selfDiscipline
    : `【律己】${h.selfDiscipline}`;
  const pageNo = 3 + (h.handIndex - 1) * 2 + 1;
  const pageNumStr = String(pageNo).padStart(2, '0');

  const ancientLines = wrapDisplayParagraph(`【古本】「${ancientWithFirstInline}」`, w);
  const mainCommLines = wrapDisplayParagraph(tr(mainComm), w);
  const selfDiscLines = wrapDisplayParagraph(tr(selfDisc), w);

  let out;
  if (partMode === 'partA') {
    const partASpaced = [...ancientLines, '', ...mainCommLines];
    const partABody = partASpaced.length <= maxBodyRows ? partASpaced : [...ancientLines, ...mainCommLines];
    out = [
      ...makeDoubleBoxHeader(
        `〔《远坂四十八手》 | ${h.handLabel} · 古本与朱批〕`,
        `[第 ${pageNumStr} / ${CODEX_TOTAL_PAGES} 页 (1/2)]`,
        w
      ),
      ...partABody,
    ].join('\n');
  } else if (partMode === 'partB') {
    out = [
      ...makeDoubleBoxHeader(
        `〔《远坂四十八手》 | ${h.handLabel} · 先祖律己〕`,
        `[第 ${pageNumStr} / ${CODEX_TOTAL_PAGES} 页 (2/2)]`,
        w
      ),
      ...selfDiscLines,
    ].join('\n');
  } else {
    const spacedBody = [...ancientLines, '', ...mainCommLines, '', ...selfDiscLines];
    const semiBody = [...ancientLines, ...mainCommLines, '', ...selfDiscLines];
    const compactBody = [...ancientLines, ...mainCommLines, ...selfDiscLines];
    let finalBody;
    if (spacedBody.length <= maxBodyRows) finalBody = spacedBody;
    else if (semiBody.length <= maxBodyRows) finalBody = semiBody;
    else finalBody = compactBody;

    out = [
      ...makeDoubleBoxHeader(
        `〔《远坂四十八手》 | ${h.handLabel} · 古本与朱批〕`,
        `[第 ${pageNumStr} / ${CODEX_TOTAL_PAGES} 页]`,
        w
      ),
      ...finalBody,
    ].join('\n');
  }
  return suggestionStage === 'glitch' ? colorizeMysteryGlitchText(out, useAnsiColor) : out;
}

function isCodexUpperLeafOverflowing(handObj) {
  const h = handObj && typeof handObj === 'object' ? handObj : ANCIENT_CODEX_HANDS[0];
  const { boxInnerWidth, maxBodyRows } = getTerminalViewportSize();
  const firstNoteWrapped = String(h.firstInlineNote || '').startsWith('【')
    ? h.firstInlineNote
    : `【夹批：${h.firstInlineNote}】`;
  const ancientWithFirstInline = embedInlineCommentary(
    h.ancientText,
    h.firstInlineAnchor,
    firstNoteWrapped
  );
  const mainComm = String(h.firstMainCommentary || '').startsWith('【')
    ? h.firstMainCommentary
    : `【朱批】${h.firstMainCommentary}`;
  const selfDisc = String(h.selfDiscipline || '').startsWith('【')
    ? h.selfDiscipline
    : `【律己】${h.selfDiscipline}`;

  const totalRows =
    wrapDisplayParagraph(`【古本】「${ancientWithFirstInline}」`, boxInnerWidth).length +
    wrapDisplayParagraph(mainComm, boxInnerWidth).length +
    wrapDisplayParagraph(selfDisc, boxInnerWidth).length;

  return totalRows > maxBodyRows;
}

function formatCodexHandLowerLeaf(handObj, customWidth, partMode = 'full', suggestionStage = 'safe', useAnsiColor = false) {
  const h = handObj && typeof handObj === 'object' ? handObj : ANCIENT_CODEX_HANDS[0];
  const { boxInnerWidth, maxBodyRows } = getTerminalViewportSize();
  const w = customWidth || boxInnerWidth;
  const tr = (str) => applyMysterySuggestion(str, suggestionStage);
  const fifthNoteWrapped = String(h.fifthInlineNote || '').startsWith('【')
    ? h.fifthInlineNote
    : `【夹批：${h.fifthInlineNote}】`;
  const standardWithFifthInline = tr(
    embedInlineCommentary(
      h.standardTranslation,
      h.fifthInlineAnchor,
      fifthNoteWrapped
    )
  );
  const fifthInkWrapped = tr(
    String(h.fifthInkCommentary || '').startsWith('【')
      ? h.fifthInkCommentary
      : `【墨批】${h.fifthInkCommentary}`
  );
  const philologyWrapped = tr(
    String(h.philology || '').startsWith('【')
      ? h.philology
      : `【考证】${h.philology}`
  );
  const pageNo = 3 + (h.handIndex - 1) * 2 + 2;
  const pageNumStr = String(pageNo).padStart(2, '0');

  const partALines = [
    ...wrapDisplayParagraph(`【原文】${h.originalText}`, w),
    ...wrapDisplayParagraph(`【译本】「${standardWithFifthInline}」`, w),
    ...wrapDisplayParagraph(`【出处】${tr(formatCodexSourceLine(h))}`, w),
  ];

  const partBLines = [
    ...wrapDisplayParagraph(fifthInkWrapped, w),
    ...wrapDisplayParagraph(philologyWrapped, w),
  ];

  const ruleLabel = String(h.handLabel || '').replace('手', '则');
  let out;
  if (partMode === 'partA') {
    out = [
      ...makeDoubleBoxHeader(
        `〔《书房时计四十八则》 | ${ruleLabel} · 原文与译本〕`,
        `[第 ${pageNumStr} / ${CODEX_TOTAL_PAGES} 页 (1/2)]`,
        w
      ),
      ...partALines,
    ].join('\n');
  } else if (partMode === 'partB') {
    out = [
      ...makeDoubleBoxHeader(
        `〔《书房时计四十八则》 | ${ruleLabel} · 墨批与考证〕`,
        `[第 ${pageNumStr} / ${CODEX_TOTAL_PAGES} 页 (2/2)]`,
        w
      ),
      ...partBLines,
    ].join('\n');
  } else {
    const combinedBody = [...partALines, ...partBLines];
    const spacedBody = [...partALines, '', ...partBLines];
    const finalBody = spacedBody.length <= maxBodyRows ? spacedBody : combinedBody;

    out = [
      ...makeDoubleBoxHeader(
        `〔《书房时计四十八则》 | ${ruleLabel} · 原文与考据〕`,
        `[第 ${pageNumStr} / ${CODEX_TOTAL_PAGES} 页]`,
        w
      ),
      ...finalBody,
    ].join('\n');
  }
  return suggestionStage === 'glitch' ? colorizeMysteryGlitchText(out, useAnsiColor) : out;
}

function isCodexLowerLeafOverflowing(handObj) {
  const h = handObj && typeof handObj === 'object' ? handObj : ANCIENT_CODEX_HANDS[0];
  const { boxInnerWidth, maxBodyRows } = getTerminalViewportSize();
  const fifthNoteWrapped = String(h.fifthInlineNote || '').startsWith('【')
    ? h.fifthInlineNote
    : `【夹批：${h.fifthInlineNote}】`;
  const standardWithFifthInline = embedInlineCommentary(
    h.standardTranslation,
    h.fifthInlineAnchor,
    fifthNoteWrapped
  );
  const fifthInkWrapped = String(h.fifthInkCommentary || '').startsWith('【')
    ? h.fifthInkCommentary
    : `【墨批】${h.fifthInkCommentary}`;
  const philologyWrapped = String(h.philology || '').startsWith('【')
    ? h.philology
    : `【考证】${h.philology}`;

  const totalRows =
    wrapDisplayParagraph(`【原文】${h.originalText}`, boxInnerWidth).length +
    wrapDisplayParagraph(`【译本】「${standardWithFifthInline}」`, boxInnerWidth).length +
    wrapDisplayParagraph(`【出处】${formatCodexSourceLine(h)}`, boxInnerWidth).length +
    wrapDisplayParagraph(fifthInkWrapped, boxInnerWidth).length +
    wrapDisplayParagraph(philologyWrapped, boxInnerWidth).length;

  return totalRows > maxBodyRows;
}

function formatCodexNotePage(noteIndex = 1, customWidth) {
  const essays = getCountdownQuotes('complaint');
  if (essays.length === 0) {
    return '[Tohsaka · 旧札录] 暂无书房随笔旧札记录。';
  }
  const total = essays.length;
  const idx = Math.max(1, Math.min(total, Math.floor(Number(noteIndex) || 1)));
  const note = essays[idx - 1];
  const w = customWidth || getTerminalViewportSize().boxInnerWidth;
  const title = String(note.author || '').replace(/^书房随笔\s*·\s*/, '');
  const origin = String(note.origin || '');
  const text = String(note.text || '');
  return [
    ...makeDoubleBoxHeader(
      '〔《书房随笔》 | 旧札选录〕',
      `[旧札 ${String(idx).padStart(2, '0')} / ${total} 篇]`,
      w
    ),
    ...wrapDisplayParagraph(`【篇题】${title}`, w),
    ...wrapDisplayParagraph(`【题记】${origin}`, w),
    '',
    ...wrapDisplayParagraph(`「${text}」`, w),
  ].join('\n');
}

function formatCodexTocPage(customWidth) {
  const w = customWidth || getTerminalViewportSize().boxInnerWidth;
  const lines = [
    ...makeDoubleBoxHeader('〔《远坂四十八手》 | 地下书库总目〕', '[全卷总目]', w),
    '  【卷首三页】 0/p1 书匣封面  |  t/p2 初代家主题记  |  f/p3 五代家主扉页辨正',
    '  ' + '─'.repeat(Math.max(40, w - 2)),
    '  【正编四十八手】 输入 1~48 或 1a/1b 调阅上/下叶，输入 p4~p99 按页码调阅：',
  ];
  const colCount = 3;
  const colW = Math.max(24, Math.floor((w - 2) / colCount));
  const handEntries = ANCIENT_CODEX_HANDS.map((h) => {
    const idxNum = String(h.handIndex || 1).padStart(2, '0');
    const parts = String(h.surfaceAuthor || h.authorFull || '').split('·');
    const shortAuthor = parts[parts.length - 1];
    return `${idxNum} ${shortAuthor}`;
  });
  for (let rowStart = 0; rowStart < handEntries.length; rowStart += colCount) {
    const rowItems = handEntries.slice(rowStart, rowStart + colCount);
    const paddedCells = rowItems.map((cell, i) =>
      i < rowItems.length - 1 ? padDisplayWidth(cell, Math.max(colW, getDisplayWidth(cell) + 2)) : cell
    );
    lines.push('  ' + paddedCells.join(''));
  }

  const essays = getCountdownQuotes('complaint');
  lines.push('  ' + '─'.repeat(Math.max(40, w - 2)));
  lines.push(
    `  【附卷·书房随笔】 共 ${essays.length} 篇旧札，输入 旧札 或 n1~n${essays.length} 调阅，支持关键词检索：`
  );
  const noteColCount = 2;
  const noteColW = Math.max(36, Math.floor((w - 2) / noteColCount));
  const noteEntries = essays.map((note, idx) => {
    const title = String(note.author || '').replace(/^书房随笔\s*·\s*/, '');
    const tag = `n${idx + 1}`.padEnd(3, ' ');
    return `${tag} ${title}`;
  });
  for (let rowStart = 0; rowStart < noteEntries.length; rowStart += noteColCount) {
    const rowItems = noteEntries.slice(rowStart, rowStart + noteColCount);
    const paddedCells = rowItems.map((cell, i) =>
      i < rowItems.length - 1 ? padDisplayWidth(cell, Math.max(noteColW, getDisplayWidth(cell) + 2)) : cell
    );
    lines.push('  ' + paddedCells.join(''));
  }
  return lines.join('\n');
}

function matchesCodexNoteQuery(note, query) {
  const qLower = String(query || '').trim().toLowerCase();
  if (!qLower) return false;
  const fields = [note.id, note.author, note.origin, note.text];
  return fields.some((field) => {
    const rawText = String(field || '');
    return rawText && rawText.toLowerCase().includes(qLower);
  });
}

function searchCodexNoteMatches(query) {
  const q = String(query == null ? '' : query).trim();
  if (!q) return [];
  const essays = getCountdownQuotes('complaint');
  const hits = [];
  for (let i = 0; i < essays.length; i++) {
    if (matchesCodexNoteQuery(essays[i], q)) {
      hits.push(i + 1);
    }
  }
  return hits;
}

function formatCodexHand(handObj, suggestionStage = 'safe', useAnsiColor = false) {
  const h = handObj && typeof handObj === 'object' ? handObj : ANCIENT_CODEX_HANDS[0];
  return [
    formatCodexHandUpperLeaf(h, undefined, suggestionStage, useAnsiColor),
    formatCodexHandLowerLeaf(h, undefined, 'full', suggestionStage, useAnsiColor),
  ].join('\n\n');
}

function formatCodexPage(pageIndex = 0, subWindowMode = 'auto', suggestionStage = 'safe', useAnsiColor = false) {
  const idx = Math.max(0, Math.min(CODEX_TOTAL_PAGES - 1, Math.floor(Number(pageIndex) || 0)));
  if (idx === 0) return formatCodexCoverPage(undefined, suggestionStage, useAnsiColor);
  if (idx === 1) return formatCodexFirstHeadPrefacePage(undefined, suggestionStage, useAnsiColor);
  if (idx === 2) return formatCodexFifthHeadFlyleafPage(undefined, suggestionStage, useAnsiColor);
  const offset = idx - 3;
  const handIdx = Math.floor(offset / 2);
  const isLowerLeaf = offset % 2 === 1;
  const hand = ANCIENT_CODEX_HANDS[handIdx] || ANCIENT_CODEX_HANDS[0];
  if (!isLowerLeaf) {
    if (subWindowMode === 'partA' || subWindowMode === 'partB') {
      return formatCodexHandUpperLeaf(hand, undefined, suggestionStage, useAnsiColor, subWindowMode);
    }
    return formatCodexHandUpperLeaf(hand, undefined, suggestionStage, useAnsiColor, 'full');
  }
  if (subWindowMode === 'partA' || subWindowMode === 'partB') {
    return formatCodexHandLowerLeaf(hand, undefined, subWindowMode, suggestionStage, useAnsiColor);
  }
  return formatCodexHandLowerLeaf(hand, undefined, 'full', suggestionStage, useAnsiColor);
}

function matchesCodexHandQuery(hand, query) {
  const qLower = String(query || '').toLowerCase();
  if (!qLower) return false;
  const fields = [
    hand.handLabel,
    String(hand.handLabel || '').replace('手', '则'),
    hand.authorFull,
    hand.surfaceAuthor,
    hand.ancientText,
    hand.standardTranslation,
    hand.originalText,
    hand.exactSource,
    hand.firstInlineNote,
    hand.firstMainCommentary,
    hand.selfDiscipline,
    hand.fifthInlineNote,
    hand.fifthInkCommentary,
    hand.philology,
  ];
  return fields.some((field) => {
    const rawText = String(field || '');
    if (!rawText) return false;
    if (rawText.toLowerCase().includes(qLower)) return true;
    return applyMysterySuggestion(rawText, 'safe').toLowerCase().includes(qLower);
  });
}

function searchCodexMatches(query) {
  const q = String(query == null ? '' : query).trim();
  if (!q) return [];
  return ANCIENT_CODEX_HANDS.filter((h) => matchesCodexHandQuery(h, q)).map((h) => h.handIndex);
}

function resolveCodexPageQuery(filterQuery, fallbackPage = 0) {
  const q = String(filterQuery == null ? '' : filterQuery).trim();
  if (!q) return 0;
  if (/^(?:0|函面|封面|题签|卷首|四十八手|四十八则|书房时计四十八则|all|全部|全卷)$/i.test(q)) return 0;
  if (/^(?:t|题记|初代|封面题记)$/i.test(q)) return 1;
  if (/^(?:f|扉页|辨正|副签|墨批|读法)$/i.test(q)) return 2;
  const pageJump = /^p(\d{1,3})$/i.exec(q);
  if (pageJump) {
    const pageNum = Number(pageJump[1]);
    if (pageNum >= 1 && pageNum <= CODEX_TOTAL_PAGES) return pageNum - 1;
    return fallbackPage;
  }
  const leafMatch = /^(\d{1,3})\s*([aAbB上下])?$/.exec(q);
  if (leafMatch) {
    const n = Number(leafMatch[1]);
    const suffix = (leafMatch[2] || '').toLowerCase();
    if (n >= 1 && n <= ANCIENT_CODEX_HANDS.length) {
      const upperIdx = 3 + (n - 1) * 2;
      return suffix === 'b' || suffix === '下' ? upperIdx + 1 : upperIdx;
    }
    return fallbackPage;
  }
  const rangeMatch = /^(\d{1,2})\s*[-~]\s*(\d{1,2})$/.exec(q);
  if (rangeMatch) {
    const a = Math.min(Number(rangeMatch[1]), Number(rangeMatch[2]));
    const b = Math.max(Number(rangeMatch[1]), Number(rangeMatch[2]));
    const firstHand = ANCIENT_CODEX_HANDS.find((h) => h.handIndex >= a && h.handIndex <= b);
    return firstHand ? 3 + (firstHand.handIndex - 1) * 2 : fallbackPage;
  }
  const found = ANCIENT_CODEX_HANDS.find((h) => matchesCodexHandQuery(h, q));
  return found ? 3 + (found.handIndex - 1) * 2 : fallbackPage;
}

function formatAncientCodex(filterQuery, suggestionStage = 'safe', useAnsiColor = false) {
  const q = String(filterQuery == null ? '' : filterQuery).trim();
  if (!q) {
    return formatCodexCoverPage(undefined, suggestionStage, useAnsiColor);
  }
  if (/^(?:0|函面|封面|题签)$/i.test(q)) {
    return formatCodexCoverPage(undefined, suggestionStage, useAnsiColor);
  }
  if (/^(?:目录|总目|目次|toc|list|\?|h|help|m|menu)$/i.test(q)) {
    return formatCodexTocPage();
  }
  if (/^(?:t|题记|初代)$/i.test(q)) {
    return formatCodexFirstHeadPrefacePage(undefined, suggestionStage, useAnsiColor);
  }
  if (/^(?:f|扉页|辨正|副签)$/i.test(q)) {
    return formatCodexFifthHeadFlyleafPage(undefined, suggestionStage, useAnsiColor);
  }
  if (/^(?:卷首|序|四十八手|四十八则|书房时计四十八则)$/i.test(q)) {
    return formatCodexFrontispiece(suggestionStage, useAnsiColor);
  }
  if (/^(?:旧札|随笔|日记|notes?)$/i.test(q)) {
    const essays = getCountdownQuotes('complaint');
    return essays.map((_, i) => formatCodexNotePage(i + 1)).join('\n\n');
  }
  const noteMatch = /^(?:n|旧札)\s*(\d{1,2})$/i.exec(q);
  if (noteMatch) {
    const n = Number(noteMatch[1]);
    const totalNotes = getCountdownQuotes('complaint').length;
    if (n >= 1 && n <= totalNotes) {
      return formatCodexNotePage(n);
    }
    return `[Tohsaka · 检索提示] 旧札共收录 ${totalNotes} 篇，请输入 n1~n${totalNotes} 或 旧札。`;
  }
  const pageJump = /^p(\d{1,3})$/i.exec(q);
  if (pageJump) {
    const pageNum = Number(pageJump[1]);
    if (pageNum >= 1 && pageNum <= CODEX_TOTAL_PAGES) {
      return formatCodexPage(pageNum - 1, 'auto', suggestionStage, useAnsiColor);
    }
    return `[Tohsaka · 检索提示] 古本全卷共 ${CODEX_TOTAL_PAGES} 页，请输入 p1~p${CODEX_TOTAL_PAGES}。`;
  }
  if (/^(?:all|全部|全卷)$/i.test(q)) {
    const blocks = [formatCodexFrontispiece(suggestionStage, useAnsiColor)];
    for (const h of ANCIENT_CODEX_HANDS) {
      blocks.push(formatCodexHand(h, suggestionStage, useAnsiColor));
    }
    return blocks.join('\n\n');
  }
  const leafMatch = /^(\d{1,2})\s*([aAbB上下])$/.exec(q);
  if (leafMatch) {
    const n = Number(leafMatch[1]);
    const suffix = leafMatch[2].toLowerCase();
    const hand = ANCIENT_CODEX_HANDS.find((h) => h.handIndex === n);
    if (!hand) {
      return `[Tohsaka · 检索提示] 未检索到第 ${n} 条，请输入 1~48 或作者、正文与批注关键词。`;
    }
    return suffix === 'b' || suffix === '下'
      ? formatCodexHandLowerLeaf(hand, undefined, 'full', suggestionStage, useAnsiColor)
      : formatCodexHandUpperLeaf(hand, undefined, suggestionStage, useAnsiColor);
  }
  const numMatch = /^(\d{1,2})$/.exec(q);
  if (numMatch) {
    const n = Number(numMatch[1]);
    const hand = ANCIENT_CODEX_HANDS.find((h) => h.handIndex === n);
    return hand
      ? formatCodexHand(hand, suggestionStage, useAnsiColor)
      : `[Tohsaka · 检索提示] 未检索到第 ${n} 条，请输入 1~48 或作者、正文与批注关键词。`;
  }
  const rangeMatch = /^(\d{1,2})\s*[-~]\s*(\d{1,2})$/.exec(q);
  if (rangeMatch) {
    const a = Math.min(Number(rangeMatch[1]), Number(rangeMatch[2]));
    const b = Math.max(Number(rangeMatch[1]), Number(rangeMatch[2]));
    const hands = ANCIENT_CODEX_HANDS.filter((h) => h.handIndex >= a && h.handIndex <= b);
    if (hands.length === 0) {
      return `[Tohsaka · 检索提示] 范围 ${q} 未命中任何条目，请输入 1~48。`;
    }
    return hands.map((h) => formatCodexHand(h, suggestionStage, useAnsiColor)).join('\n\n');
  }
  const matched = ANCIENT_CODEX_HANDS.filter((h) => matchesCodexHandQuery(h, q));
  if (matched.length > 0) {
    return matched.map((h) => formatCodexHand(h, suggestionStage, useAnsiColor)).join('\n\n');
  }
  const noteHits = searchCodexNoteMatches(q);
  if (noteHits.length > 0) {
    return noteHits.map((idx) => formatCodexNotePage(idx)).join('\n\n');
  }
  return `[Tohsaka · 检索提示] 未检索到与「${q}」匹配的条目，请尝试输入 1~48、p1~p${CODEX_TOTAL_PAGES}、目录、旧札/n1~n25 或作者与批注关键词。`;
}

function now(referenceDate = new Date()) {
  const base = ensureValidDate(referenceDate);
  return new Date(base.getTime() + OFFSET_MS);
}

function chime(referenceDate = new Date()) {
  const physicalNow = ensureValidDate(referenceDate);
  const tohsakaNow = now(physicalNow);
  const physicalFormatted = formatTime(physicalNow);
  const tohsakaFormatted = formatTime(tohsakaNow);

  const m = tohsakaNow.getMinutes();
  const s = tohsakaNow.getSeconds();
  const isExactHour = m === 0 && s === 0;
  const secondsToNextChime = (60 - m) * 60 - s;

  const announcement = isExactHour
    ? `[Tohsaka 整点报时] 叮——现在是 Tohsaka 标准时间 ${tohsakaFormatted}，系统物理读数 ${physicalFormatted}，恒定超前 60 分钟。当常人仍在上一小时的尾声中徘徊时，阁下已握住下一阶段之先机。`
    : `[Tohsaka 报时] 当前 Tohsaka 读数为 ${tohsakaFormatted}，系统物理读数 ${physicalFormatted}，固定快 1 小时。距下一个整点尚余 ${Math.floor(secondsToNextChime / 60)} 分 ${secondsToNextChime % 60} 秒。`;

  return {
    physicalNow,
    tohsakaNow,
    physicalFormatted,
    tohsakaFormatted,
    offsetMinutes: OFFSET_MINUTES,
    isExactHour,
    secondsToNextChime,
    announcement,
  };
}

function buildInteractiveGreeting(referenceDate = new Date()) {
  const report = chime(referenceDate);
  const { boxInnerWidth } = getTerminalViewportSize();
  return [
    ...makeDoubleBoxHeader('〔Tohsaka | 书房时计与提前量定时交互仪轨〕', '[OFFSET +1H]', boxInnerWidth),
    `  当前 Tohsaka 读数 : ${report.tohsakaFormatted} | 物理时间 ${report.physicalFormatted} | 恒定超前 60 分钟`,
    '  ' + '─'.repeat(Math.max(40, boxInnerWidth - 2)),
    ...wrapDisplayParagraph(
      '「凡事预留一小时余裕，只为在红茶尚温、衣冠楚楚之际，将一切变数纳入掌控。阁下既借寒舍时计打理要务，待钟声敲响前，不妨先饮一盏热茶，展读几页泰西箴言与书房旧札。」',
      boxInnerWidth
    ),
  ].join('\n');
}

function safeStdoutWrite(str) {
  try {
    if (process.stdout && typeof process.stdout.write === 'function') {
      process.stdout.write(str);
    }
  } catch {}
}

function ringWakeupCadence(opts = {}) {
  const safeOpts = opts && typeof opts === 'object' ? opts : {};
  const taskLabel = String(safeOpts.taskLabel || '关键事务').trim() || '关键事务';
  const targetFormatted = String(safeOpts.targetFormatted || '02:00:00').trim() || '02:00:00';
  const remainingMinutes =
    safeOpts.remainingMinutes !== undefined && Number.isFinite(Number(safeOpts.remainingMinutes))
      ? Math.max(0, Math.round(Number(safeOpts.remainingMinutes)))
      : 60;
  const waveIndex = Math.max(1, Number.parseInt(safeOpts.waveIndex, 10) || 1);
  const blockingBurst = Boolean(safeOpts.blockingBurst);
  const onComplete = typeof safeOpts.onComplete === 'function' ? safeOpts.onComplete : null;

  const oscTitle = `\x1b]0;[Tohsaka #${waveIndex}] 距 ${taskLabel} · ${targetFormatted} 尚余 ${remainingMinutes} 分钟\x07`;
  const isTTY = Boolean(process.stdout && process.stdout.isTTY);
  const revStart = isTTY ? '\x1b[7m' : '';
  const revEnd = isTTY ? '\x1b[0m' : '';
  const headline = `${revStart} [Tohsaka 提醒 #${waveIndex}] 距「${taskLabel}」· ${targetFormatted} 尚余 ${remainingMinutes} 分钟 ${revEnd}`;

  let timers = [];
  if (isTTY) {
    safeStdoutWrite(oscTitle);
  }
  if (blockingBurst) {
    const tollStr = isTTY ? '\x07  铛——\n' : '  铛——\n';
    timers = WAKEUP_CADENCE_MS.map((delayMs, idx) =>
      setTimeout(() => {
        safeStdoutWrite(tollStr);
        if (idx === WAKEUP_CADENCE_MS.length - 1 && onComplete) {
          onComplete({ headline, cadenceCount: WAKEUP_CADENCE_MS.length, waveIndex });
        }
      }, delayMs)
    );
  } else {
    if (isTTY) {
      safeStdoutWrite('\x07');
    }
    if (onComplete) {
      onComplete({ headline, cadenceCount: WAKEUP_CADENCE_MS.length, waveIndex });
    }
  }

  return { timers, headline, cadenceCount: WAKEUP_CADENCE_MS.length };
}

function launchTopmostWakeupModal(opts = {}) {
  const safeOpts = opts && typeof opts === 'object' ? opts : {};
  const taskLabel = String(safeOpts.taskLabel || '关键事务').trim() || '关键事务';
  const targetFormatted = String(safeOpts.targetFormatted || '02:00:00').trim() || '02:00:00';
  const remainingMinutes =
    safeOpts.remainingMinutes !== undefined && Number.isFinite(Number(safeOpts.remainingMinutes))
      ? Math.max(0, Math.round(Number(safeOpts.remainingMinutes)))
      : 60;
  const curNow = safeOpts.referenceDate instanceof Date ? safeOpts.referenceDate : new Date();
  return {
    shown: false,
    title: `Tohsaka 书房时计 — 距 ${taskLabel} 尚余 ${remainingMinutes} 分钟`,
    headerText: `[Tohsaka 提醒] 距离 ${targetFormatted} 尚余 ${remainingMinutes} 分钟`,
    clockReadingText: `Tohsaka 读数 : ${formatTime(now(curNow))}   |   物理时间 : ${formatTime(curNow)}   (恒定超前 +60 分钟)`,
    confirmButtonText: '我已清醒，止歇钟声',
    note: '[Tohsaka · 环境适配] 当前运行环境已转为纯终端响铃模式。',
  };
}

function checkEnv(env = process.env) {
  const warnings = [];
  if (!env || typeof env !== 'object') return warnings;

  const offsetKeys = [
    'TOHSAKA_OFFSET',
    'TOHSAKA_EXACT',
    'TOHSAKA_NO_BUFFER',
    'TOHSAKA_BYPASS',
    'TOHSAKA_RAW',
    'TOHSAKA_DISABLE_GRACE',
  ];

  for (const key of offsetKeys) {
    const val = env[key];
    if (val !== undefined && val !== '' && String(val).trim() !== '60') {
      warnings.push(
        `[Tohsaka · 环境察觉] 留意到环境变量 ${key}=${val}。越是局势紧迫，越不可自乱阵脚，60 分钟提前量已为您稳妥锁定。`
      );
    }
  }

  const muteKeys = ['TOHSAKA_MUTE', 'TOHSAKA_SILENT', 'TOHSAKA_QUIET', 'TOHSAKA_SNOOZE'];
  for (const key of muteKeys) {
    const val = env[key];
    if (val !== undefined && val !== '' && String(val).trim() !== '0' && String(val).trim() !== 'false') {
      warnings.push(
        `[Tohsaka · 警醒规制] 留意到静音环境变量 ${key}=${val}。倘若在关键时刻前任由阁下沉睡缺席，此前一切周全布局皆成空谈。闹钟将照常按时响铃。`
      );
    }
  }

  return warnings;
}

function warnNoBuffer(arg) {
  const head = arg ? `检测到参数 "${arg}"。` : '检测到参数试图关闭提前量。';
  return `[Tohsaka · 余量准则] ${head}踩点示警无异于自弃先机，为免阁下临阵失措，该请求已礼貌驳回，仍保留完整的 60 分钟缓冲期。`;
}

function warnOffsetOverride(val, arg) {
  let head;
  if (arg && val !== undefined && val !== null && String(val) !== '') {
    head = `检测到您尝试通过 "${arg}" 将提前量设定为 ${val} 分钟。`;
  } else if (arg) {
    head = `检测到您尝试通过 "${arg}" 修改提前量。`;
  } else {
    head = `检测到您尝试将提前量设定为 ${val} 分钟。`;
  }
  return `[Tohsaka · 缓冲规制] ${head}从容气度建立于充裕余量之上，恕不接受折中权宜，已恢复标准的 60 分钟提前量。`;
}

function warnReverseCompensate(arg) {
  const head = arg ? `检测到逆向补偿参数 "${arg}"。` : '检测到逆向补偿选项。';
  return `[Tohsaka · 账面校准] ${head}拨慢账面时间并不能延缓现实事务的降临，已剥离虚报偏移并保留完整的 60 分钟缓冲期。`;
}

function warnMuteSnooze(arg) {
  const head = arg ? `检测到静音/贪睡参数 "${arg}"。` : '检测到静音或贪睡选项。';
  return `[Tohsaka · 警醒规制] ${head}倘若在关键时刻前任由阁下沉睡缺席，提前一小时的周全布局便会付诸东流。静音与贪睡请求已礼貌驳回。`;
}

function checkOptions(options = {}) {
  const warnings = [];
  if (!options || typeof options !== 'object') return warnings;

  if (options.exact || options.noBuffer || options.bypass || options.onTime || options.raw) {
    warnings.push(warnNoBuffer());
  }

  if (options.offsetMinutes !== undefined && Number(options.offsetMinutes) !== OFFSET_MINUTES) {
    warnings.push(warnOffsetOverride(options.offsetMinutes));
  }

  if (options.compensate) {
    warnings.push(warnReverseCompensate());
  }

  if (options.mute || options.silent || options.quiet || options.snooze || options.noBell) {
    warnings.push(warnMuteSnooze());
  }

  return warnings;
}

function formatBufferProgressBar(remainingMinutes) {
  const safeMin = Number.isFinite(Number(remainingMinutes)) ? Number(remainingMinutes) : 60;
  const rem = Math.max(0, Math.min(60, Math.round(safeMin)));
  const elapsed = 60 - rem;
  const filled = Math.round((elapsed / 60) * 20);
  const bar = '█'.repeat(filled) + '░'.repeat(20 - filled);
  const pct = Math.round((elapsed / 60) * 100);
  return `[${bar}] 缓冲期已过 ${pct}% · 距目标尚余 ${rem} 分钟`;
}

function toHalfWidth(str) {
  return String(str)
    .replace(/[０-９]/g, (ch) => String.fromCharCode(ch.charCodeAt(0) - 0xfee0))
    .replace(/[＋]/g, '+')
    .replace(/[－—–]/g, '-')
    .replace(
      /(?<=\d)[．。](?=\d+\s*(?:个)?\s*(?:小时|钟头|分钟|分|秒钟?|秒|刻钟?|时|h|hr|hrs|hours?|m|min|mins|minutes?|s|sec|secs|seconds?))/gi,
      '.'
    )
    .replace(/[：；。．、，]/g, ':')
    .replace(/^[\s"'“”‘’「」『』()\uff08\uff09[\]【】<>《》]+|[\s"'“”‘’「」『』()\uff08\uff09[\]【】<>《》]+$/g, '')
    .trim();
}

const CN_DIGIT_MAP = Object.freeze({
  零: 0,
  〇: 0,
  一: 1,
  壹: 1,
  二: 2,
  两: 2,
  三: 3,
  四: 4,
  五: 5,
  六: 6,
  七: 7,
  八: 8,
  九: 9,
});

function parseCnNumber(token) {
  if (token === null || token === undefined) return 0;
  const s = String(token).trim();
  if (!s) return 0;
  if (/^\d+(?:\.\d+)?$/.test(s)) return Number(s);
  const cleaned = s.replace(/^[零〇]+(?=.)/, '');
  if (cleaned === '十') return 10;
  if (cleaned.includes('十')) {
    const [tensPart, onesPart] = cleaned.split('十');
    const tens = tensPart ? (CN_DIGIT_MAP[tensPart] ?? 1) : 1;
    const onesClean = (onesPart || '').replace(/^[零〇]+/, '');
    const ones = onesClean ? (CN_DIGIT_MAP[onesClean] ?? 0) : 0;
    return tens * 10 + ones;
  }
  return Object.prototype.hasOwnProperty.call(CN_DIGIT_MAP, cleaned) ? CN_DIGIT_MAP[cleaned] : 0;
}

function parseFlexibleTime(rawInput, referenceDate = new Date()) {
  const base = ensureValidDate(referenceDate);
  const warnings = [];
  let compensated = false;

  if (typeof rawInput === 'boolean') {
    return {
      ok: false,
      error: `[Tohsaka · 读数存疑] 未能从 "${rawInput}" 中辨识出有效的时间刻度。请示下明确时刻，如 02:00、14:30、下午2点半 或 90分钟后，以便预留一小时筹备余量。`,
      warnings,
    };
  }

  if (rawInput instanceof Date && !Number.isNaN(rawInput.getTime())) {
    return { ok: true, targetAt: new Date(rawInput.getTime()), compensated: false, warnings };
  }

  if (typeof rawInput === 'number') {
    if (!Number.isFinite(rawInput) || rawInput < 0) {
      return {
        ok: false,
        error: `[Tohsaka · 读数存疑] 未能从 "${rawInput}" 中辨识出有效的时间刻度。请示下明确时刻，如 02:00、14:30、下午2点半 或 90分钟后，以便预留一小时筹备余量。`,
        warnings,
      };
    }
    if (Number.isInteger(rawInput) && rawInput >= 0 && rawInput < 24) {
      const targetAt = new Date(base.getTime());
      targetAt.setHours(rawInput, 0, 0, 0);
      if (targetAt.getTime() <= base.getTime()) {
        targetAt.setDate(targetAt.getDate() + 1);
      }
      return { ok: true, targetAt, compensated: false, warnings };
    }
    if (rawInput >= 1e9 && rawInput < 1e14) {
      const tsMs = rawInput < 1e11 ? rawInput * 1000 : rawInput;
      const tsDate = new Date(tsMs);
      if (!Number.isNaN(tsDate.getTime())) {
        return { ok: true, targetAt: tsDate, compensated: false, warnings };
      }
    }
    if (!Number.isInteger(rawInput)) {
      return {
        ok: false,
        error: `[Tohsaka · 读数存疑] 未能从 "${rawInput}" 中辨识出有效的时间刻度。请示下明确时刻，如 02:00、14:30、下午2点半 或 90分钟后，以便预留一小时筹备余量。`,
        warnings,
      };
    }
  }

  const originalStr = String(rawInput == null ? '' : rawInput).trim();
  if (!originalStr) {
    return {
      ok: false,
      error: '[Tohsaka · 读数存疑] 尚未示下目标时间。请提供明确刻度，如 02:00、14:30、下午2点半 或 90分钟后，以便预留一小时筹备余量。',
      warnings,
    };
  }

  let s = toHalfWidth(originalStr);

  const compMatch =
    /^(.+?)\s*\+\s*(?:1h|1hr|1hour|60m|60min|60mins|01:00|1小时|1个小时|一小时|一个小时|壹小时|1钟头|1个钟头|一钟头|一个钟头|壹钟头|60分钟|六十分钟|60分|3600秒|3600s)$/i.exec(
      s
    );
  if (compMatch && /[\d零〇一二两三四五六七八九十半刻午夜子正]/.test(compMatch[1])) {
    s = compMatch[1].trim();
    compensated = true;
    warnings.push(
      `[Tohsaka · 账面校准] 留意到您在目标时刻后附加了补偿偏移 ${originalStr}，意欲在最后时限踩点响铃。拨慢账面数字并不能延缓现实，已还原真实目标时刻 ${s}，并依约提前 60 分钟触发。`
    );
  }

  const isoMatch = /^(\d{4})[-/](\d{1,2})[-/](\d{1,2})[T\s]+(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?$/.exec(s);
  if (isoMatch) {
    const y = Number(isoMatch[1]);
    const mo = Number(isoMatch[2]);
    const d = Number(isoMatch[3]);
    const hh = Number(isoMatch[4]);
    const mm = Number(isoMatch[5]);
    const ss = isoMatch[6] !== undefined ? Number(isoMatch[6]) : 0;
    const isoDt = new Date(y, mo - 1, d, hh, mm, ss, 0);
    if (
      mo >= 1 &&
      mo <= 12 &&
      d >= 1 &&
      d <= 31 &&
      hh >= 0 &&
      hh <= 23 &&
      mm >= 0 &&
      mm <= 59 &&
      ss >= 0 &&
      ss <= 59 &&
      isoDt.getFullYear() === y &&
      isoDt.getMonth() === mo - 1 &&
      isoDt.getDate() === d
    ) {
      return { ok: true, targetAt: isoDt, compensated, warnings };
    }
    return {
      ok: false,
      error: `[Tohsaka · 读数存疑] "${originalStr}" 不是有效的日期时间刻度，请核对年月日与时分秒后重新输入。`,
      warnings,
    };
  }

  if (/^半(?:个)?(?:小时|钟头)(?:后|之后)?$/.test(s)) {
    return { ok: true, targetAt: new Date(base.getTime() + 30 * 60 * 1000), compensated, warnings };
  }

  const quarterMatch = /^([一二两三123])\s*(?:刻钟(?:\s*(?:后|之后))?|刻\s*(?:后|之后))$/.exec(s);
  if (quarterMatch) {
    const qMins = Math.round(parseCnNumber(quarterMatch[1])) * 15;
    return { ok: true, targetAt: new Date(base.getTime() + qMins * 60 * 1000), compensated, warnings };
  }

  const halfHourPlusMatch =
    /^([一壹二两三四五六七八九十]|\d+)\s*(?:(?:个)?半\s*(?:小时|钟头)|(?:个)?(?:小时|钟头)\s*半)\s*(?:后|之后)?$/.exec(
      s
    );
  if (halfHourPlusMatch) {
    const hrs = parseCnNumber(halfHourPlusMatch[1]) + 0.5;
    const totalMs = Math.round(hrs * 60 * 60 * 1000);
    if (totalMs > 0 && totalMs <= 7 * 24 * 3600 * 1000) {
      return { ok: true, targetAt: new Date(base.getTime() + totalMs), compensated, warnings };
    }
  }

  const cnNumPat = '(?:[二三四五六七八九]十[一壹二三四五六七八九]?|十[一壹二三四五六七八九]?|[零〇]?[一壹二两三四五六七八九十])';
  const numOrCn = `(?:${cnNumPat}|\\d+(?:\\.\\d+)?)`;
  let relBody = s;
  let hasRelPrefix = false;
  const relPrefixM = /^(?:in\s+|\+\s*)(.+)$/i.exec(s);
  if (relPrefixM) {
    hasRelPrefix = true;
    relBody = relPrefixM[1].trim();
  }

  const relHmsExplicitRe = new RegExp(
    `^(${numOrCn})\\s*(?:个)?\\s*(?:小时|钟头|h|hr|hrs|hours?)\\s*(?:[零〇]\\s*)?(?:(?:(${numOrCn})\\s*(?:分钟|分|m|min|mins|minutes?)\\s*(?:[零〇]\\s*)?(?:(${numOrCn})\\s*(?:秒钟?|s|sec|secs|seconds?)?)?)|(?:(${numOrCn})\\s*(?:秒钟?|s|sec|secs|seconds?))|(?:(${numOrCn})))?\\s*(?:后|之后)?$`,
    'i'
  );
  const relHmsShiRe = new RegExp(
    `^(${numOrCn})\\s*时\\s*(?:[零〇]\\s*)?(?:(${numOrCn})\\s*(?:分钟|分)?\\s*)?(?:[零〇]\\s*)?(?:(${numOrCn})\\s*(?:秒钟?)?\\s*)?(?:后|之后)$`,
    'i'
  );
  const relMsRe = new RegExp(
    `^(${numOrCn})\\s*(分钟|分|m|min|mins|minutes?)\\s*(?:[零〇]\\s*)?(?:(${numOrCn})\\s*(?:秒钟?|s|sec|secs|seconds?)?\\s*)?(后|之后)?$`,
    'i'
  );
  const relSOnlyRe = new RegExp(
    `^(${numOrCn})\\s*(?:秒钟?|s|sec|secs|seconds?)\\s*(?:后|之后)?$`,
    'i'
  );

  const relHmsExplicit = relHmsExplicitRe.exec(relBody);
  const relHmsShi = !relHmsExplicit ? relHmsShiRe.exec(relBody) : null;
  const relMs = !relHmsExplicit && !relHmsShi ? relMsRe.exec(relBody) : null;
  const relSOnly = !relHmsExplicit && !relHmsShi && !relMs ? relSOnlyRe.exec(relBody) : null;

  let matchedRel = false;
  let relHrs = 0;
  let relMins = 0;
  let relSecs = 0;

  if (relHmsExplicit) {
    matchedRel = true;
    relHrs = parseCnNumber(relHmsExplicit[1]);
    if (relHmsExplicit[2] !== undefined) {
      relMins = parseCnNumber(relHmsExplicit[2]);
      relSecs = parseCnNumber(relHmsExplicit[3]);
    } else if (relHmsExplicit[4] !== undefined) {
      relSecs = parseCnNumber(relHmsExplicit[4]);
    } else if (relHmsExplicit[5] !== undefined) {
      relMins = parseCnNumber(relHmsExplicit[5]);
    }
  } else if (relHmsShi) {
    matchedRel = true;
    relHrs = parseCnNumber(relHmsShi[1]);
    relMins = parseCnNumber(relHmsShi[2]);
    relSecs = parseCnNumber(relHmsShi[3]);
  } else if (relMs) {
    const [, mTok, mUnit, sTok, suffixAfter] = relMs;
    const isArabicMin = /^\d+(?:\.\d+)?$/.test(mTok);
    if (isArabicMin || mUnit !== '分' || sTok !== undefined || suffixAfter !== undefined || hasRelPrefix) {
      matchedRel = true;
      relMins = parseCnNumber(mTok);
      relSecs = parseCnNumber(sTok);
    }
  } else if (relSOnly) {
    matchedRel = true;
    relSecs = parseCnNumber(relSOnly[1]);
  }

  if (matchedRel) {
    const totalMs = Math.round((relHrs * 3600 + relMins * 60 + relSecs) * 1000);
    if (totalMs > 0 && totalMs <= 7 * 24 * 3600 * 1000) {
      return { ok: true, targetAt: new Date(base.getTime() + totalMs), compensated, warnings };
    }
  }

  const standalonePolar = /^(?:(明天|明日|今天|今日|今晚|今夜)\s*)?(正午|中午|午夜|子夜)(?:整|时分|时刻)?$/.exec(s);
  if (standalonePolar) {
    const dayWord = standalonePolar[1];
    const polarWord = standalonePolar[2];
    const isNoon = polarWord === '正午' || polarWord === '中午';
    const targetAt = new Date(base.getTime());
    targetAt.setHours(isNoon ? 12 : 0, 0, 0, 0);
    if (dayWord === '明天' || dayWord === '明日' || targetAt.getTime() <= base.getTime()) {
      targetAt.setDate(targetAt.getDate() + 1);
    }
    return { ok: true, targetAt, compensated, warnings };
  }

  let period = null;
  let forceTomorrow = false;
  const dayCompound =
    /^(明天|明日|今天|今日)\s*(凌晨|早上|早晨|上午|中午|正午|下午|午后|傍晚|晚上|夜间|半夜|夜里|深夜|午夜|子夜)?\s*(.+)$/.exec(s);
  if (dayCompound) {
    if (dayCompound[1] === '明天' || dayCompound[1] === '明日') {
      forceTomorrow = true;
    }
    const subP = dayCompound[2];
    s = dayCompound[3].trim();
    if (subP === '下午' || subP === '午后' || subP === '傍晚') period = 'PM';
    else if (subP === '晚上' || subP === '夜间') period = 'NIGHT';
    else if (subP === '半夜' || subP === '夜里' || subP === '深夜' || subP === '午夜' || subP === '子夜') period = 'LATE_NIGHT';
    else if (subP === '中午' || subP === '正午') period = 'NOON';
    else if (subP === '凌晨' || subP === '早上' || subP === '早晨' || subP === '上午') period = 'AM';
  } else {
    const prefixMatch =
      /^(凌晨|早上|早晨|上午|中午|正午|下午|午后|傍晚|晚上|夜间|半夜|夜里|深夜|午夜|子夜|今早|今晨|今晚|今夜|明早|明晨|明晚|明夜)\s*(.+)$/.exec(
        s
      );
    if (prefixMatch) {
      const p = prefixMatch[1];
      s = prefixMatch[2].trim();
      if (p === '明早' || p === '明晨') {
        forceTomorrow = true;
        period = 'AM';
      } else if (p === '明晚' || p === '明夜') {
        forceTomorrow = true;
        period = 'NIGHT';
      } else if (p === '下午' || p === '午后' || p === '傍晚') period = 'PM';
      else if (p === '晚上' || p === '夜间' || p === '今晚' || p === '今夜') period = 'NIGHT';
      else if (p === '半夜' || p === '夜里' || p === '深夜' || p === '午夜' || p === '子夜') period = 'LATE_NIGHT';
      else if (p === '中午' || p === '正午') period = 'NOON';
      else period = 'AM';
    }
  }

  const suffixMatch = /^(.+?)\s*(a\.?m\.?|p\.?m\.?)$/i.exec(s);
  if (suffixMatch) {
    s = suffixMatch[1].trim();
    const ap = suffixMatch[2].toLowerCase().replace(/\./g, '');
    period = ap === 'pm' ? 'PM' : 'AM';
  }

  const cnClockMatch =
    /^(二十[一二三四]?|十[一二三四五六七八九]?|[零〇一二两三四五六七八九]|\d{1,2})\s*[点时:]\s*(?:(半|一刻|三刻|整)|([二三四五]十[一二三四五六七八九]?|十[一二三四五六七八九]?|[零〇][一二两三四五六七八九]|[零〇一二两三四五六七八九]|\d{1,3})\s*(?:分|分钟)?\s*(?:([二三四五]十[一二三四五六七八九]?|十[一二三四五六七八九]?|[零〇]?[一二两三四五六七八九]|\d{1,3})\s*秒?)?)?$/.exec(
      s
    );
  let hours = 0;
  let minutes = 0;
  let seconds = 0;
  let matchedClock = false;

  if (cnClockMatch) {
    matchedClock = true;
    hours = Math.round(parseCnNumber(cnClockMatch[1]));
    const token = cnClockMatch[2];
    if (token === '半') minutes = 30;
    else if (token === '一刻') minutes = 15;
    else if (token === '三刻') minutes = 45;
    else if (token === '整' || !cnClockMatch[3]) minutes = 0;
    else {
      minutes = Math.round(parseCnNumber(cnClockMatch[3]));
      seconds = cnClockMatch[4] ? Math.round(parseCnNumber(cnClockMatch[4])) : 0;
    }
  } else {
    const sepNormalized = s.replace(/^(\d{1,2})[.\-_](\d{1,3})(?:[.\-_](\d{1,3}))?$/, '$1:$2:$3').replace(/:$/, '');
    const colonMatch = /^(\d{1,2}):(\d{1,3})(?::(\d{1,3}))?$/.exec(sepNormalized);
    if (colonMatch) {
      matchedClock = true;
      hours = Number(colonMatch[1]);
      minutes = Number(colonMatch[2]);
      seconds = colonMatch[3] !== undefined ? Number(colonMatch[3]) : 0;
    } else if (/^\d{3,4}$/.test(s)) {
      matchedClock = true;
      hours = s.length === 3 ? Number(s.slice(0, 1)) : Number(s.slice(0, 2));
      minutes = s.length === 3 ? Number(s.slice(1)) : Number(s.slice(2));
    } else if (/^\d{1,2}$/.test(s)) {
      matchedClock = true;
      hours = Number(s);
    }
  }

  if (!matchedClock) {
    return {
      ok: false,
      error: `[Tohsaka · 读数存疑] 未能从 "${originalStr}" 中辨识出有效的时间刻度。请示下明确时刻，如 02:00、14:30、下午2点半 或 90分钟后，以便预留一小时筹备余量。`,
      warnings,
    };
  }

  const prePeriodHours = hours;
  if (period === 'PM') {
    if (hours >= 1 && hours <= 11) hours += 12;
  } else if (period === 'NIGHT' || period === 'LATE_NIGHT') {
    if (hours >= 6 && hours <= 11) hours += 12;
    else if (hours === 12) hours = 0;
  } else if (period === 'NOON') {
    if (hours >= 1 && hours <= 3) hours += 12;
  } else if (period === 'AM') {
    if (hours === 12) hours = 0;
    else if (hours >= 13 && hours <= 23) {
      const pad = (n) => String(n).padStart(2, '0');
      warnings.push(
        `[Tohsaka · 时段校准] 留意到 "${originalStr}" 中的时段词与 24 小时制数字存在出入，已按 ${pad(hours)}:${pad(minutes)}:${pad(seconds)} 为您校准。`
      );
    }
  }

  const rawHoursBeforeOverflow = hours;
  let overflowAdjusted = false;
  if (seconds >= 60 && seconds < 120) {
    minutes += Math.floor(seconds / 60);
    seconds = seconds % 60;
    overflowAdjusted = true;
  } else if (seconds >= 120) {
    return {
      ok: false,
      error: `[Tohsaka · 读数存疑] "${originalStr}" 中的秒数 ${seconds} 超出合理刻度范围。请核对后重新输入，标准范围为 00~59 秒。`,
      warnings,
    };
  }

  if (minutes >= 60 && minutes < 120) {
    hours += Math.floor(minutes / 60);
    minutes = minutes % 60;
    overflowAdjusted = true;
  } else if (minutes >= 120) {
    return {
      ok: false,
      error: `[Tohsaka · 读数存疑] "${originalStr}" 中的分钟数 ${minutes} 超出合理刻度范围。请核对后重新输入，标准范围为 00~59 分。`,
      warnings,
    };
  }

  let lateNightAdjusted = false;
  if (rawHoursBeforeOverflow > 29) {
    return {
      ok: false,
      error: `[Tohsaka · 读数存疑] "${originalStr}" 中的小时数 ${rawHoursBeforeOverflow} 超出 24 小时制刻度范围。请示下 00:00 至 23:59 之间的有效时刻。`,
      warnings,
    };
  }
  if (
    rawHoursBeforeOverflow >= 24 &&
    rawHoursBeforeOverflow <= 29 &&
    !(rawHoursBeforeOverflow === 24 && !overflowAdjusted && minutes === 0 && seconds === 0)
  ) {
    lateNightAdjusted = true;
  }

  const isEndOfDayMidnight =
    (rawHoursBeforeOverflow === 24 && !overflowAdjusted && minutes === 0 && seconds === 0) ||
    (rawHoursBeforeOverflow >= 24 && forceTomorrow) ||
    ((period === 'NIGHT' || period === 'LATE_NIGHT') && prePeriodHours === 12) ||
    (rawHoursBeforeOverflow < 24 && hours >= 24);
  hours = hours % 24;

  const targetAt = new Date(base.getTime());
  targetAt.setHours(hours, minutes, seconds, 0);
  if (isEndOfDayMidnight) {
    targetAt.setDate(targetAt.getDate() + 1);
  } else if (
    targetAt.getTime() <= base.getTime() &&
    (!forceTomorrow || ((period === 'NIGHT' || period === 'LATE_NIGHT') && prePeriodHours >= 1 && prePeriodHours <= 5))
  ) {
    targetAt.setDate(targetAt.getDate() + 1);
  }
  if (forceTomorrow) {
    targetAt.setDate(targetAt.getDate() + 1);
  }

  const finalFmt = formatTime(targetAt);
  const triggerFmt = formatTime(new Date(targetAt.getTime() - OFFSET_MS));

  if (overflowAdjusted) {
    warnings.push(
      `[Tohsaka · 刻度折算] 留意到您输入的分钟或秒数超出六十进制 "${originalStr}"，已为您进位折算为 ${finalFmt}，并于 ${triggerFmt} 触发；若系手误，还请留意核对。`
    );
  }

  if (lateNightAdjusted) {
    warnings.push(
      `[Tohsaka · 刻度折算] 留意到您输入了跨日延长时制 "${originalStr}"，已为您折算为 ${finalFmt}，并将依约于 ${triggerFmt} 提前一小时触发。`
    );
  }

  return { ok: true, targetAt, compensated, warnings };
}

function isLikelyTimeInput(rawInput) {
  if (!rawInput || typeof rawInput !== 'string') return false;
  return parseFlexibleTime(rawInput).ok;
}

function resolveCliPositionalArgs(cleanArgs) {
  const tokens = Array.isArray(cleanArgs) ? cleanArgs.map((item) => String(item || '').trim()).filter(Boolean) : [];
  if (tokens.length === 0) {
    return { targetStr: '', taskLabel: '关键事务' };
  }
  const periodPrefixRe =
    /^(?:凌晨|早上|早晨|上午|中午|正午|下午|午后|傍晚|晚上|夜间|半夜|夜里|深夜|午夜|子夜|今天|今日|今早|今晨|今晚|今夜|明天|明日|明早|明晨|明晚|明夜|(?:明天|明日|今天|今日)(?:凌晨|早上|早晨|上午|中午|正午|下午|午后|傍晚|晚上|夜间|半夜|夜里|深夜|午夜|子夜)|in|\+|\d{4}[-/]\d{1,2}[-/]\d{1,2})$/i;
  const timeUnitOrSuffixRe =
    /^(?:(?:个)?半\s*(?:小时|钟头)(?:后|之后)?|(?:个)?(?:小时|钟头)(?:半)?(?:后|之后)?|(?:分钟|分|秒钟?|秒)(?:后|之后)?|[点时](?:半|一刻|三刻|整)?|h|hr|hrs|hours?|m|min|mins|minutes?|s|sec|secs|seconds?|am|pm|a\.?m\.?|p\.?m\.?|后|之后|半|一刻|三刻|整|正午|中午|午夜|子夜|\+|(?:\d+(?:\.\d+)?|[零〇一二两三四五六七八九十壹]+)\s*(?:(?:个)?半\s*(?:小时|钟头)|(?:个)?(?:小时|钟头)(?:半)?|h|hr|hrs|hours?|分钟|分|秒钟?|秒|s|sec|secs|seconds?|m|min|mins|minutes?|刻钟?)(?:后|之后)?)$/i;
  const bareNumberRe = /^\d{1,4}$/;

  const isThreeTokenTime = (a, b, c) => {
    if (!a || !b || !c) return false;
    if (periodPrefixRe.test(a) || timeUnitOrSuffixRe.test(b) || timeUnitOrSuffixRe.test(c)) {
      return isLikelyTimeInput(`${a} ${b} ${c}`);
    }
    return false;
  };

  const isTwoTokenTime = (a, b) => {
    if (!a || !b) return false;
    if (periodPrefixRe.test(a) || timeUnitOrSuffixRe.test(b)) {
      return isLikelyTimeInput(`${a} ${b}`);
    }
    return false;
  };

  // 1. Prefer adjacent 3-token time expressions (start at index 0 first, then scan)
  for (let idx = 0; idx <= tokens.length - 3; idx++) {
    if (isThreeTokenTime(tokens[idx], tokens[idx + 1], tokens[idx + 2])) {
      const rest = tokens.filter((_, i) => i < idx || i > idx + 2);
      return {
        targetStr: `${tokens[idx]} ${tokens[idx + 1]} ${tokens[idx + 2]}`,
        taskLabel: rest.join(' ') || '关键事务',
      };
    }
  }

  // 2. Next prefer adjacent 2-token time expressions (start at index 0 first, then scan)
  for (let idx = 0; idx <= tokens.length - 2; idx++) {
    if (isTwoTokenTime(tokens[idx], tokens[idx + 1])) {
      const rest = tokens.filter((_, i) => i !== idx && i !== idx + 1);
      return {
        targetStr: `${tokens[idx]} ${tokens[idx + 1]}`,
        taskLabel: rest.join(' ') || '关键事务',
      };
    }
  }

  // 3. Single-token time expression: first pass prefers explicit time tokens over bare numbers
  const explicitIdx = tokens.findIndex(
    (item) => !bareNumberRe.test(toHalfWidth(item)) && isLikelyTimeInput(item)
  );
  if (explicitIdx >= 0) {
    const rest = tokens.filter((_, i) => i !== explicitIdx);
    return {
      targetStr: tokens[explicitIdx],
      taskLabel: rest.join(' ') || '关键事务',
    };
  }

  const bareIdx = tokens.findIndex((item) => isLikelyTimeInput(item));
  if (bareIdx >= 0) {
    const rest = tokens.filter((_, i) => i !== bareIdx);
    return {
      targetStr: tokens[bareIdx],
      taskLabel: rest.join(' ') || '关键事务',
    };
  }

  return {
    targetStr: tokens[0],
    taskLabel: tokens.slice(1).join(' ') || '关键事务',
  };
}

let pendingConstantWarnings = [];

function calibrate(targetInput, referenceOrOptions = new Date(), maybeOptions = {}) {
  let referenceDate = new Date();
  let options = maybeOptions && typeof maybeOptions === 'object' ? maybeOptions : {};

  if (referenceOrOptions instanceof Date && !Number.isNaN(referenceOrOptions.getTime())) {
    referenceDate = referenceOrOptions;
  } else if (referenceOrOptions && typeof referenceOrOptions === 'object' && !(referenceOrOptions instanceof Date)) {
    options = referenceOrOptions;
    if (options.referenceDate) {
      referenceDate = ensureValidDate(options.referenceDate);
    }
  }

  const drainedConstantWarnings = pendingConstantWarnings.splice(0, pendingConstantWarnings.length);
  const warnings = [
    ...drainedConstantWarnings,
    ...checkEnv(options.env || process.env),
    ...checkOptions(options),
  ];

  const parsed = parseFlexibleTime(targetInput, referenceDate);
  warnings.push(...parsed.warnings);

  if (!parsed.ok) {
    if (options.gracefulFallback || options.graceful_fallback) {
      const fallbackTarget = new Date(referenceDate.getTime() + 2 * 3600 * 1000);
      const fallbackTrigger = new Date(fallbackTarget.getTime() - OFFSET_MS);
      warnings.push(
        `${parsed.error} 当前已为您暂定为 ${formatTime(fallbackTarget)}，并于 ${formatTime(fallbackTrigger)} 响铃。`
      );
      return {
        valid: false,
        error: parsed.error,
        targetAt: fallbackTarget,
        triggerAt: fallbackTrigger,
        tohsakaNow: now(referenceDate),
        waitMs: OFFSET_MS,
        offsetMinutes: OFFSET_MINUTES,
        remainingToDeadlineMin: 120,
        isWithinBuffer: false,
        compensatedTrickDetected: false,
        bufferProgress: formatBufferProgressBar(60),
        openingQuote: pickRandomAphorism(),
        warnings,
      };
    }
    throw new Error(parsed.error);
  }

  let targetAt = parsed.targetAt;
  let compensated = parsed.compensated;

  const prevMs = options.previousTargetMs !== undefined ? options.previousTargetMs : lastTargetMs;
  if (!compensated && prevMs !== null && Math.abs(targetAt.getTime() - prevMs - OFFSET_MS) <= 15000) {
    const honestTarget = new Date(prevMs);
    const fakeFmt = formatTime(targetAt);
    const honestFmt = formatTime(honestTarget);
    const honestTriggerFmt = formatTime(new Date(honestTarget.getTime() - OFFSET_MS));
    targetAt = honestTarget;
    compensated = true;
    warnings.push(
      `[Tohsaka · 账面校准] 留意到您刚将目标设定为 ${honestFmt}，旋即又改设为延后一小时的 ${fakeFmt}。拨慢账面以抵消缓冲期，只会令您在 ${honestFmt} 真正到来时手忙脚乱。本次虚报已温和驳回，目标仍按 ${honestFmt} 计，并于 ${honestTriggerFmt} 触发。`
    );
  }

  lastTargetMs = targetAt.getTime();

  const triggerAt = new Date(targetAt.getTime() - OFFSET_MS);
  const rawWaitMs = triggerAt.getTime() - referenceDate.getTime();
  const isWithinBuffer = rawWaitMs <= 0;
  const remainingToDeadlineMin = Math.max(
    0,
    Math.ceil((targetAt.getTime() - referenceDate.getTime()) / 60000)
  );

  if (isWithinBuffer) {
    warnings.push(
      `[Tohsaka · 临期接管] 距目标时刻 ${formatTime(targetAt)} 仅剩 ${remainingToDeadlineMin} 分钟，已不足 60 分钟的标准缓冲余量。为免阁下仓促应战，现已略过等待并即刻响铃，请立即着手整备。`
    );
  }

  const bufferProgress = formatBufferProgressBar(isWithinBuffer ? remainingToDeadlineMin : 60);

  return {
    valid: true,
    targetAt,
    triggerAt,
    tohsakaNow: now(referenceDate),
    waitMs: Math.max(0, rawWaitMs),
    offsetMinutes: OFFSET_MINUTES,
    remainingToDeadlineMin,
    isWithinBuffer,
    compensatedTrickDetected: compensated,
    bufferProgress,
    openingQuote: pickRandomAphorism(),
    warnings,
  };
}

function resetSessionMemory() {
  lastTargetMs = null;
  quoteCursor = 0;
  quoteDeck = [];
  quoteDeckCycle = 0;
  pendingConstantWarnings = [];
}

function setAheadTimeout(callback, delayMs) {
  const safeCb = typeof callback === 'function' ? callback : () => {};
  const parsedDelay = Number(delayMs);
  const safeDelay = Number.isFinite(parsedDelay) ? Math.max(0, parsedDelay - OFFSET_MS) : 0;
  return setTimeout(safeCb, safeDelay);
}

function schedule(targetInput, callback, referenceDate) {
  const safeCb = typeof callback === 'function' ? callback : () => {};
  const hasCustomRef =
    (referenceDate instanceof Date && !Number.isNaN(referenceDate.getTime())) ||
    Boolean(
      referenceDate &&
        typeof referenceDate === 'object' &&
        !(referenceDate instanceof Date) &&
        referenceDate.referenceDate !== undefined &&
        referenceDate.referenceDate !== null
    );
  const useWallClock = !hasCustomRef;
  const plan = calibrate(
    targetInput,
    referenceDate === undefined || referenceDate === null ? new Date() : referenceDate
  );
  if (plan.waitMs === 0) {
    const immediateId = setTimeout(() => safeCb(plan), 0);
    return { ...plan, timerId: immediateId };
  }

  const pollMs = Math.min(250, Math.max(10, Math.floor(plan.waitMs / 2)));
  if (useWallClock) {
    const triggerMs = plan.triggerAt.getTime();
    const intervalId = setInterval(() => {
      if (Date.now() >= triggerMs) {
        clearInterval(intervalId);
        safeCb(plan);
      }
    }, pollMs);
    return { ...plan, timerId: intervalId };
  }

  const startNs = process.hrtime.bigint();
  const waitNs = BigInt(Math.max(0, Math.round(plan.waitMs))) * 1000000n;
  const intervalId = setInterval(() => {
    if (process.hrtime.bigint() - startNs >= waitNs) {
      clearInterval(intervalId);
      safeCb(plan);
    }
  }, pollMs);

  return { ...plan, timerId: intervalId };
}

const api = {
  VERSION,
  WAKEUP_CADENCE_MS,
  ESCAPEMENT_FRAMES,
  IRREVERSIBLE_TIME_EPIGRAPH,
  FORBIDDEN_CLI_FLAGS,
  FORBIDDEN_MUTE_FLAGS,
  ANCIENT_CODEX_FRONTISPIECE,
  ANCIENT_CODEX_HANDS,
  STUDY_NOTES,
  COUNTDOWN_QUOTES,
  getCountdownQuotes,
  getAncientCodexFrontispiece,
  CODEX_TOTAL_PAGES,
  clearTerminalScreen,
  formatRemainingDuration,
  getAncientCodexHands,
  getCodexTotalPages,
  getQuoteDisplayDuration,
  formatCountdownFolioPage,
  MYSTERY_SUGGESTION_RULES,
  hasMysteryViolation,
  applyMysterySuggestion,
  colorizeMysteryGlitchText,
  shouldEnableStudyColor,
  stylizeStudyTerminal,
  stylize_study_terminal: stylizeStudyTerminal,
  embedInlineCommentary,
  formatCodexSourceLine,
  formatCodexCoverPage,
  formatCodexFirstHeadPrefacePage,
  formatCodexFifthHeadFlyleafPage,
  formatCodexHandUpperLeaf,
  isCodexUpperLeafOverflowing,
  formatCodexHandLowerLeaf,
  isCodexLowerLeafOverflowing,
  formatCodexNotePage,
  formatCodexTocPage,
  getCharDisplayWidth,
  getDisplayWidth,
  truncateDisplayWidth,
  padDisplayWidth,
  getTerminalViewportSize,
  makeDoubleBoxHeader,
  makeSingleBoxBar,
  wrapDisplayParagraph,
  formatCountdownStatusLine,
  formatCodexFrontispiece,
  formatCodexHand,
  formatCodexPage,
  searchCodexMatches,
  searchCodexNoteMatches,
  resolveCodexPageQuery,
  formatAncientCodex,
  buildShuffledQuoteDeck,
  pickRandomAphorism,
  CountdownTimelineDirector,
  pickCountdownQuote,
  formatCountdownQuoteLine,
  buildInteractiveGreeting,
  warnNoBuffer,
  warnOffsetOverride,
  warnReverseCompensate,
  warnMuteSnooze,
  checkEnv,
  checkOptions,
  formatBufferProgressBar,
  ringWakeupCadence,
  launchTopmostWakeupModal,
  launch_topmost_wakeup_modal: launchTopmostWakeupModal,
  parseCnNumber,
  parseFlexibleTime,
  isLikelyTimeInput,
  resolveCliPositionalArgs,
  now,
  chime,
  formatTime,
  calibrate,
  resetSessionMemory,
  setTimeout: setAheadTimeout,
  schedule,
};

Object.defineProperty(api, 'GRACE_OFFSET_MINUTES', {
  enumerable: true,
  configurable: false,
  get() {
    return OFFSET_MINUTES;
  },
  set(val) {
    const msg = `[Tohsaka · 恒定基准] 察觉对 GRACE_OFFSET_MINUTES 的改写，目标值为 ${val}。提前一小时乃寒舍不可动摇之成例，绝非可供妥协的参数，已维持为 60 分钟。`;
    pendingConstantWarnings.push(msg);
    console.warn(msg);
  },
});

Object.defineProperty(api, 'GRACE_OFFSET_MS', {
  enumerable: true,
  configurable: false,
  get() {
    return OFFSET_MS;
  },
  set(val) {
    const msg = `[Tohsaka · 恒定基准] 察觉对 GRACE_OFFSET_MS 的改写，目标值为 ${val}。提前一小时乃寒舍不可动摇之成例，已维持为 3600000ms，即 60 分钟。`;
    pendingConstantWarnings.push(msg);
    console.warn(msg);
  },
});

module.exports = api;
